    ssl_session_cache         shared:SSL:10m;
    ssl_session_timeout       1d;
    ssl_session_tickets       off;

    # OCSP stapling
    ssl_stapling        on;
    ssl_stapling_verify on;
    resolver            1.1.1.1 8.8.8.8 valid=60s;
    resolver_timeout    5s;

    # Security headers
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
    add_header X-Content-Type-Options    "nosniff"                                      always;
    add_header X-Frame-Options           "DENY"                                         always;
    add_header Referrer-Policy           "strict-origin-when-cross-origin"              always;
    add_header Permissions-Policy        "camera=(), microphone=(), geolocation=()"     always;

    # Request limits
    client_max_body_size 20m;

    # ----- Health (unauthenticated) ------------------------------------------

    location = /health {
        proxy_pass       http://fastapi/health;
        proxy_set_header Host $host;
        access_log       off;
    }

    # External alias so monitoring can reach the signaling service
    location = /signal/health {
        proxy_pass http://signaling/health;
        access_log off;
    }

    # ----- REST API ----------------------------------------------------------

    location /api/ {
        proxy_pass         http://fastapi/api/;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header   X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
    }

    # ----- Signed media (auth_request validates HMAC sig before serving) -----

    location /media/ {
        auth_request /api/media/auth;
        alias        /var/app-media/;
        gzip         off;
        add_header   Cache-Control        "private, no-transform" always;
        add_header   X-Content-Type-Options "nosniff"             always;
    }

    # Internal subrequest — FastAPI validates the signed URL
    location = /api/media/auth {
        internal;
        proxy_pass              http://fastapi;
        proxy_pass_request_body off;
        proxy_set_header        Content-Length    "";
        proxy_set_header        X-Original-URI    $request_uri;
        proxy_set_header        X-Forwarded-Proto $scheme;
    }

    # ----- Signaling WebSocket -----------------------------------------------

    location /signal {
        proxy_pass         http://signaling;
        proxy_http_version 1.1;
        proxy_set_header   Upgrade    $http_upgrade;
        proxy_set_header   Connection "upgrade";
        proxy_set_header   Host       $host;
        proxy_set_header   X-Real-IP  $remote_addr;
        proxy_read_timeout 300s;
        gzip               off;
    }
}

