import 'package:dio/dio.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../config/app_config.dart';
import '../storage/secure_storage.dart';
import 'token_interceptor.dart';

// ── Placeholder auth state ────────────────────────────────────────────────────
// Expanded in prompt 12 with real login/logout logic.

class AuthState {
  final String? accessToken;
  const AuthState({this.accessToken});
}

class AuthNotifier extends StateNotifier<AuthState> {
  AuthNotifier() : super(const AuthState());

  void setAccessToken(String token) =>
      state = AuthState(accessToken: token);

  void clear() => state = const AuthState();
}

final authStateProvider =
    StateNotifierProvider<AuthNotifier, AuthState>((_) => AuthNotifier());

// ── Dio client ────────────────────────────────────────────────────────────────

final dioProvider = Provider<Dio>((ref) {
  final secure = ref.watch(secureStorageProvider);

  final interceptor = TokenInterceptor(
    getAccessToken: () => ref.read(authStateProvider).accessToken,
    // TODO: prompt 12 — replace with real refresh implementation
    refreshTokens: () async {
      final refreshToken = await secure.readRefreshToken();
      final deviceId = await secure.readDeviceId();
      if (refreshToken == null) return false;

      try {
        // Bypass the token interceptor by using a standalone Dio instance.
        final plain = Dio(BaseOptions(baseUrl: AppConfig.apiBaseUrl));
        final resp = await plain.post<Map<String, dynamic>>(
          '/api/auth/refresh',
          data: {'refresh_token': refreshToken, 'device_id': deviceId},
        );
        final newAccess = resp.data?['access_token'] as String?;
        final newRefresh = resp.data?['refresh_token'] as String?;
        if (newAccess == null || newRefresh == null) return false;

        ref.read(authStateProvider.notifier).setAccessToken(newAccess);
        await secure.saveRefreshToken(newRefresh);
        return true;
      } catch (_) {
        return false;
      }
    },
    onAuthExpired: () async {
      await secure.deleteRefreshToken();
      ref.read(authStateProvider.notifier).clear();
      // TODO: prompt 12 — navigate to /login via GoRouter
    },
  );

  return Dio(
    BaseOptions(
      baseUrl: AppConfig.apiBaseUrl,
      connectTimeout: const Duration(seconds: 10),
      receiveTimeout: const Duration(seconds: 30),
      headers: {'Content-Type': 'application/json'},
    ),
  )..interceptors.add(interceptor);
});

