import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'core/config/theme.dart';
import 'core/network/dio_client.dart';

// GoRouter reads auth state synchronously; prompt 12 will replace the
// redirect logic once the real auth flow is wired.
final _routerProvider = Provider<GoRouter>((ref) {
  final authState = ref.watch(authStateProvider);

  return GoRouter(
    initialLocation: '/splash',
    redirect: (context, state) {
      final loggedIn = authState.accessToken != null;
      final onAuthRoute = state.matchedLocation == '/login' ||
          state.matchedLocation == '/register' ||
          state.matchedLocation == '/otp' ||
          state.matchedLocation == '/splash';

      // TODO: prompt 12 — expand with persistent session check on splash
      if (!loggedIn && !onAuthRoute) return '/login';
      return null;
    },
    routes: [
      GoRoute(
        path: '/splash',
        builder: (_, __) => const _Placeholder('Splash'),
      ),
      GoRoute(
        path: '/login',
        builder: (_, __) => const _Placeholder('Login'),
      ),
      GoRoute(
        path: '/register',
        builder: (_, __) => const _Placeholder('Register'),
      ),
      GoRoute(
        path: '/otp',
        builder: (_, __) => const _Placeholder('OTP Verification'),
