/* ============================================================
   Lumio Design System — Tokens
   Load this once per page. Tokens are scoped to [data-theme="dark"]
   and [data-theme="light"] on any ancestor element, so you can show
   both themes side-by-side on the same page.
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  /* -------- Type scale -------- */
  --font-sans: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;

  --text-display:    28px;   /* h0 — modal hero titles, very rare */
  --text-h1:         24px;   /* h1 — screen titles, app bar */
  --text-h2:         22px;   /* h2 — section heads inside cards */
  --text-body:       16px;   /* base body */
  --text-secondary:  14px;   /* timestamps, secondary list lines */
  --text-caption:    13px;   /* bottom-nav labels, micro-copy */

  --leading-tight:   1.25;
  --leading-body:    1.4;

  --weight-regular:  400;
  --weight-medium:   500;
  --weight-semibold: 600;
  --weight-bold:     700;

  --tracking-tight:  -0.01em;
  --tracking-body:   0;

  /* -------- Spacing scale (4dp base) -------- */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-14: 56px;
  --space-18: 72px;

  /* -------- Radii -------- */
  --radius-sm:   8px;   /* small chips */
  --radius-md:   12px;  /* small cards, list-row containers */
  --radius-lg:   16px;  /* inputs */
  --radius-xl:   20px;  /* nested cards */
  --radius-2xl:  24px;  /* primary cards / tiles */
  --radius-pill: 999px;

  /* -------- Accents (shared across themes) -------- */
  --accent-primary:    #5B7CFA;  /* indigo-blue */
  --accent-primary-hi: #7A93FB;  /* hover/active brighten */
  --accent-primary-lo: #4566D8;  /* pressed */

  --accent-danger:     #FF6B6B;  /* coral, destructive/decline */
  --accent-danger-hi:  #FF8888;
  --accent-danger-lo:  #E55757;

  --accent-success:    #34C77B;  /* green, accept/online */
  --accent-success-hi: #4DD68F;
  --accent-success-lo: #2BAA68;

  /* Muted avatar tints (used only behind initials) */
  --avatar-1: #6A7AA8;
  --avatar-2: #8B7AA8;
  --avatar-3: #A87A8B;
  --avatar-4: #7AA89E;
  --avatar-5: #A89B7A;

  /* -------- Motion -------- */
  --ease-standard: cubic-bezier(.2, 0, 0, 1);
  --ease-exit:     cubic-bezier(.4, 0, 1, 1);
  --dur-fast:   120ms;
  --dur-base:   240ms;
  --dur-screen: 320ms;
}

/* -------- Dark theme (default) -------- */
:root,
[data-theme="dark"] {
  --bg:           #1A2235;   /* canvas */
  --surface:      #222B42;   /* card */
  --surface-hi:   #2A344E;   /* card pressed/hover */
  --surface-lo:   #1F273C;   /* nested */
  --hairline:     #37425E;
  --hairline-strong: #4A5878;

  --fg-1:         #F2F4F8;   /* primary text */
  --fg-2:         #9AA3B8;   /* secondary text */
  --fg-3:         #6E7895;   /* tertiary / disabled-ish */

  --scrim:        rgba(10, 16, 30, .55);
  --inner-glow:   inset 0 1px 0 rgba(255, 255, 255, .04);
  --shadow-float: 0 8px 24px rgba(0, 0, 0, .22), inset 0 1px 0 rgba(255,255,255,.05);
}

/* -------- Light theme -------- */
[data-theme="light"] {
  --bg:           #F4F6FB;
  --surface:      #FFFFFF;
  --surface-hi:   #F0F3FA;
  --surface-lo:   #F8FAFE;
  --hairline:     #E3E7F0;
  --hairline-strong: #CDD4E1;

  --fg-1:         #1A2235;
  --fg-2:         #6B7488;
  --fg-3:         #9098A8;

  --scrim:        rgba(26, 34, 53, .35);
  --inner-glow:   inset 0 -1px 0 rgba(26, 34, 53, .02);
  --shadow-float: 0 8px 24px rgba(26, 34, 53, .08), inset 0 1px 0 rgba(255,255,255,.6);
}

/* ============================================================
   Semantic element styles — drop into any page using this CSS.
   ============================================================ */

html, body {
  background: var(--bg);
  color: var(--fg-1);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  font-weight: var(--weight-regular);
  line-height: var(--leading-body);
  letter-spacing: var(--tracking-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, .h1 {
  font-size: var(--text-h1);
  font-weight: var(--weight-semibold);
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
  color: var(--fg-1);
  margin: 0;
}

h2, .h2 {
  font-size: var(--text-h2);
  font-weight: var(--weight-semibold);
  line-height: var(--leading-tight);
  color: var(--fg-1);
  margin: 0;
}

.display {
  font-size: var(--text-display);
  font-weight: var(--weight-semibold);
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
  color: var(--fg-1);
}

p, .body {
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--fg-1);
  margin: 0;
}

.secondary {
  font-size: var(--text-secondary);
  color: var(--fg-2);
  line-height: var(--leading-body);
}

.caption {
  font-size: var(--text-caption);
  font-weight: var(--weight-medium);
  color: var(--fg-2);
  line-height: var(--leading-tight);
}

/* Cards / tiles */
.card {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--radius-2xl);
  box-shadow: var(--inner-glow);
}

.card--nested {
  border-radius: var(--radius-xl);
  background: var(--surface-lo);
}

/* Pill button */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  height: 48px;
  padding: 0 var(--space-6);
  border-radius: var(--radius-pill);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  font-weight: var(--weight-semibold);
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform var(--dur-fast) var(--ease-standard),
              background-color var(--dur-fast) var(--ease-standard);
  user-select: none;
}
.btn:active { transform: scale(.98); }

.btn--primary {
  background: var(--accent-primary);
  color: #FFFFFF;
}
.btn--primary:hover { background: var(--accent-primary-hi); }
.btn--primary:active { background: var(--accent-primary-lo); }

.btn--ghost {
  background: transparent;
  color: var(--fg-1);
  border-color: var(--hairline-strong);
}
.btn--ghost:hover { background: var(--surface-hi); }

.btn--danger {
  background: var(--accent-danger);
  color: #FFFFFF;
}

/* Input — rounded field with floating label */
.field {
  position: relative;
  display: block;
}
.field input,
.field textarea {
  width: 100%;
  height: 56px;
  padding: 22px 16px 8px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--radius-lg);
  color: var(--fg-1);
  font: inherit;
  font-size: var(--text-body);
  outline: none;
  transition: border-color var(--dur-fast) var(--ease-standard);
}
.field input:focus,
.field textarea:focus {
  border-color: var(--accent-primary);
}
.field label {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--fg-2);
  pointer-events: none;
  transition: all var(--dur-fast) var(--ease-standard);
  font-size: var(--text-body);
}
.field input:focus + label,
.field input:not(:placeholder-shown) + label,
.field textarea:focus + label,
.field textarea:not(:placeholder-shown) + label {
  top: 14px;
  transform: translateY(0);
  font-size: var(--text-caption);
  color: var(--fg-2);
}

/* Focus ring (a11y) */
:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 2px;
}

