// LoginScreen.jsx — phone + password, with inline errors and loading state.
// NOTE: fields are inlined (not factored out) so React keeps the input's
// focus across keystrokes — a nested component would remount per render.

function LoginScreen({ theme = 'dark' }) {
  const t = useT(theme);
  const [phone, setPhone] = React.useState('');
  const [pwd, setPwd] = React.useState('');
  const [showPwd, setShowPwd] = React.useState(false);
  const [phoneFocus, setPhoneFocus] = React.useState(false);
  const [pwdFocus, setPwdFocus] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);
  const [errors, setErrors] = React.useState({});

  const formatPhone = (raw) => {
    const d = raw.replace(/\D/g, '').slice(0, 10);
    const a = d.slice(0, 3), b = d.slice(3, 6), c = d.slice(6, 10);
    if (d.length > 6) return `(${a}) ${b}-${c}`;
    if (d.length > 3) return `(${a}) ${b}`;
    if (d.length > 0) return `(${a}`;
    return '';
  };

  const onSubmit = () => {
    const e = {};
    const digits = phone.replace(/\D/g, '');
    if (digits.length < 10) e.phone = 'Enter your 10-digit phone number.';
    if (pwd.length < 6) e.pwd = 'Your password is at least 6 characters.';
    setErrors(e);
    if (Object.keys(e).length) return;
    setSubmitting(true);
    setTimeout(() => setSubmitting(false), 2400);
  };

  const phoneFloat = phoneFocus || phone.length > 0;
  const pwdFloat = pwdFocus || pwd.length > 0;
  const phoneBorder = errors.phone ? FL_ACCENT.danger : (phoneFocus ? FL_ACCENT.primary : t.hairline);
  const pwdBorder = errors.pwd ? FL_ACCENT.danger : (pwdFocus ? FL_ACCENT.primary : t.hairline);

  const errorRow = (msg) => (
    <div style={{
      display: 'flex', alignItems: 'center', gap: 6,
      color: FL_ACCENT.danger, fontSize: 13, fontWeight: 500,
      padding: '8px 4px 0 16px',
    }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
      </svg>
      <span>{msg}</span>
    </div>
  );

  // US flag glyph (SVG, 22×16, rounded rect) — small, no emoji dependency
  const USFlag = (
    <svg width="22" height="16" viewBox="0 0 22 16" style={{ borderRadius: 3, overflow: 'hidden', flexShrink: 0 }} aria-label="United States">
      <defs>
        <clipPath id="flagClip"><rect width="22" height="16" rx="2"/></clipPath>
      </defs>
      <g clipPath="url(#flagClip)">
        <rect width="22" height="16" fill="#B22234"/>
        {[...Array(7)].map((_, i) => (
          <rect key={i} y={1.23 * (2 * i + 1)} width="22" height="1.23" fill="#fff"/>
        ))}
        <rect width="10" height="7.4" fill="#3C3B6E"/>
      </g>
    </svg>
  );

  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', background: t.bg, overflow: 'hidden' }}>
      {/* Minimal app bar: just the logo, centered */}
      <div style={{ height: 56, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
        <svg viewBox="0 0 64 32" width="60" height="30" fill="none">
          <circle cx="20" cy="16" r="11" stroke={FL_ACCENT.primary} strokeWidth="2.5"/>
          <circle cx="36" cy="16" r="11" stroke={t.fg1} strokeWidth="2.5" opacity="0.85"/>
        </svg>
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '20px 24px 32px', display: 'flex', flexDirection: 'column' }}>
        <div style={{ marginTop: 24, marginBottom: 32 }}>
          <h1 style={{ margin: 0, fontSize: 32, fontWeight: 600, letterSpacing: '-0.02em', color: t.fg1 }}>
            Welcome back
          </h1>
          <p style={{ margin: '10px 0 0', fontSize: 16, color: t.fg2, lineHeight: 1.45, maxWidth: '34ch' }}>
            Sign in to stay close to family.
          </p>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {/* Phone field */}
          <div>
            <div style={{
              position: 'relative', display: 'flex', alignItems: 'stretch',
              background: t.surface, border: `1px solid ${phoneBorder}`,
              borderRadius: 18, boxShadow: t.innerGlow,
              transition: 'border-color 120ms', minHeight: 64,
            }}>
              <div style={{
                display: 'flex', alignItems: 'center', gap: 8,
                padding: '0 14px 0 16px',
                borderRight: `1px solid ${t.hairline}`,
                color: t.fg1, fontSize: 16, fontWeight: 500, flexShrink: 0,
              }}>
                {USFlag}
                <span style={{ color: t.fg2 }}>+1</span>
              </div>
              <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center' }}>
                <label style={{
                  position: 'absolute', left: 16,
                  top: phoneFloat ? 10 : '50%',
                  transform: phoneFloat ? 'translateY(0)' : 'translateY(-50%)',
                  fontSize: phoneFloat ? 12 : 16, fontWeight: 500,
                  color: errors.phone ? FL_ACCENT.danger : t.fg2,
                  pointerEvents: 'none',
                  transition: 'all 120ms cubic-bezier(.2,0,0,1)',
                  letterSpacing: 0.2,
                }}>Phone number</label>
                <input
                  value={phone}
                  onChange={e => { setPhone(formatPhone(e.target.value)); if (errors.phone) setErrors({ ...errors, phone: undefined }); }}
                  onFocus={() => setPhoneFocus(true)}
                  onBlur={() => setPhoneFocus(false)}
                  inputMode="numeric"
                  placeholder={phoneFloat ? '(555) 000-0000' : ''}
                  style={{
                    flex: 1, width: '100%', boxSizing: 'border-box',
                    background: 'transparent', border: 'none', outline: 'none',
                    color: t.fg1, fontFamily: "'Inter', sans-serif", fontSize: 17, fontWeight: 500,
                    padding: '24px 16px 10px 16px', letterSpacing: 0.1,
                  }}
                />
              </div>
            </div>
            {errors.phone && errorRow(errors.phone)}
          </div>

          {/* Password field */}
          <div>
            <div style={{
              position: 'relative', display: 'flex', alignItems: 'stretch',
              background: t.surface, border: `1px solid ${pwdBorder}`,
              borderRadius: 18, boxShadow: t.innerGlow,
              transition: 'border-color 120ms', minHeight: 64,
            }}>
              <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center' }}>
                <label style={{
                  position: 'absolute', left: 16,
                  top: pwdFloat ? 10 : '50%',
                  transform: pwdFloat ? 'translateY(0)' : 'translateY(-50%)',
                  fontSize: pwdFloat ? 12 : 16, fontWeight: 500,
                  color: errors.pwd ? FL_ACCENT.danger : t.fg2,
                  pointerEvents: 'none',
                  transition: 'all 120ms cubic-bezier(.2,0,0,1)',
                  letterSpacing: 0.2,
                }}>Password</label>
                <input
                  value={pwd}
                  onChange={e => { setPwd(e.target.value); if (errors.pwd) setErrors({ ...errors, pwd: undefined }); }}
                  onFocus={() => setPwdFocus(true)}
                  onBlur={() => setPwdFocus(false)}
                  type={showPwd ? 'text' : 'password'}
                  style={{
                    flex: 1, width: '100%', boxSizing: 'border-box',
                    background: 'transparent', border: 'none', outline: 'none',
                    color: t.fg1, fontFamily: "'Inter', sans-serif", fontSize: 17, fontWeight: 500,
                    padding: '24px 56px 10px 16px',
                    letterSpacing: showPwd ? 0.1 : 2,
                  }}
                />
              </div>
              <div style={{ display: 'flex', alignItems: 'center', padding: '0 8px', flexShrink: 0 }}>
                <button onClick={() => setShowPwd(!showPwd)} aria-label={showPwd ? 'Hide password' : 'Show password'} style={{
                  width: 44, height: 44, borderRadius: 999, border: 'none', cursor: 'pointer',
                  background: 'transparent', color: t.fg2,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  {showPwd
                    ? <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
                    : <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>}
                </button>
              </div>
            </div>
            {errors.pwd && errorRow(errors.pwd)}
          </div>

          <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: -4 }}>
            <button style={{
              border: 'none', background: 'transparent', cursor: 'pointer',
              color: FL_ACCENT.primary, fontFamily: "'Inter', sans-serif",
              fontSize: 14, fontWeight: 600, padding: '8px 4px',
              whiteSpace: 'nowrap',
            }}>Forgot password?</button>
          </div>
        </div>

        <button
          onClick={onSubmit}
          disabled={submitting}
          style={{
            marginTop: 24,
            width: '100%', height: 56,
            borderRadius: 999, border: 'none',
            background: submitting ? '#4566D8' : FL_ACCENT.primary,
            color: '#fff',
            fontFamily: "'Inter', sans-serif", fontSize: 17, fontWeight: 600,
            cursor: submitting ? 'default' : 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
            transition: 'background 120ms',
            boxShadow: '0 8px 24px rgba(91,124,250,0.25)',
          }}
        >
          {submitting && (
            <svg width="20" height="20" viewBox="0 0 32 32" fill="none" style={{ animation: 'fl-login-spin 1.1s linear infinite' }}>
              <circle cx="16" cy="16" r="13" stroke="rgba(255,255,255,0.3)" strokeWidth="2.5"/>
              <path d="M16 3 a13 13 0 0 1 13 13" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" fill="none"/>
            </svg>
          )}
          {submitting ? 'Signing in…' : 'Log in'}
        </button>

        <div style={{ flex: 1 }} />

        <div style={{
          marginTop: 32, paddingTop: 20,
          borderTop: `1px solid ${t.hairline}`,
          textAlign: 'center',
        }}>
          <span style={{ color: t.fg2, fontSize: 15 }}>New here? </span>
          <button style={{
            border: 'none', background: 'transparent', cursor: 'pointer',
            color: FL_ACCENT.primary, fontFamily: "'Inter', sans-serif",
            fontSize: 15, fontWeight: 600, padding: 0,
          }}>Create an account</button>
        </div>
      </div>

      <style>{`@keyframes fl-login-spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

Object.assign(window, { LoginScreen });

