// ContactsScreen.jsx — Family contacts list with search, quick actions, empty state.

function ContactsScreen({ theme = 'dark', empty = false, active = 'contacts' }) {
  const t = useT(theme);

  const fam = [
    { name: 'Grandma Rose', phone: '+1 (415) 555 · 0142', online: true },
    { name: 'Grandpa Joe',  phone: '+1 (415) 555 · 0118' },
    { name: 'Mom Sarah',    phone: '+1 (415) 555 · 0091', online: true },
    { name: 'Dad Mike',     phone: '+1 (415) 555 · 0044' },
    { name: 'Aunt Karen',   phone: '+1 (415) 555 · 0177' },
    { name: 'Uncle Pete',   phone: '+1 (415) 555 · 0210' },
    { name: 'Cousin Jamie', phone: '+1 (415) 555 · 0309' },
  ];

  const EmptyArt = (
    <svg width="160" height="120" viewBox="0 0 160 120" fill="none">
      <circle cx="80" cy="60" r="56" fill={FL_ACCENT.primary} opacity="0.08"/>
      <g stroke={FL_ACCENT.primary} strokeWidth="2.5" fill="none" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="58" cy="48" r="11"/>
        <circle cx="98" cy="48" r="11"/>
        <path d="M40 86 a18 18 0 0 1 36 0"/>
        <path d="M80 86 a18 18 0 0 1 36 0"/>
      </g>
      <circle cx="115" cy="40" r="9" stroke={t.hairlineStrong} strokeWidth="2" fill={t.surfaceLo}/>
      <line x1="111" y1="40" x2="119" y2="40" stroke={t.fg2} strokeWidth="2" strokeLinecap="round"/>
      <line x1="115" y1="36" x2="115" y2="44" stroke={t.fg2} strokeWidth="2" strokeLinecap="round"/>
    </svg>
  );

  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', background: t.bg, overflow: 'hidden', position: 'relative' }}>
      {/* App bar */}
      <div style={{
        height: 64, padding: '0 8px 0 20px', flexShrink: 0,
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      }}>
        <div style={{ fontSize: 26, fontWeight: 600, letterSpacing: '-0.01em', color: t.fg1 }}>Family</div>
        <button aria-label="Add family member" style={{
          width: 44, height: 44, borderRadius: 999, border: 'none', cursor: 'pointer',
          background: 'transparent', color: t.fg1,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}><Icon name="add" size={22}/></button>
      </div>

      {/* Search */}
      <div style={{ padding: '0 16px 12px', flexShrink: 0 }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: 10,
          height: 48, padding: '0 14px',
          background: t.surfaceLo, border: `1px solid ${t.hairline}`,
          borderRadius: 999, boxShadow: t.innerGlow,
        }}>
          <Icon name="search" size={18} stroke={t.fg2}/>
          <span style={{ fontSize: 15, color: t.fg2 }}>Search family</span>
        </div>
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: empty ? '0 16px 32px' : '0 16px 16px' }}>
        {empty ? (
          <div style={{
            flex: 1, display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center',
            padding: '60px 24px', minHeight: '100%', textAlign: 'center',
          }}>
            {EmptyArt}
            <h2 style={{ margin: '16px 0 0', fontSize: 22, fontWeight: 600, color: t.fg1, letterSpacing: '-0.01em' }}>
              No family yet
            </h2>
            <p style={{ margin: '8px 0 20px', fontSize: 15, color: t.fg2, lineHeight: 1.5, maxWidth: '28ch' }}>
              Add your family members to start chatting.
            </p>
            <button style={{
              display: 'inline-flex', alignItems: 'center', gap: 8,
              height: 48, padding: '0 22px', borderRadius: 999, border: 'none',
              background: FL_ACCENT.primary, color: '#fff', cursor: 'pointer',
              fontFamily: "'Inter', sans-serif", fontSize: 16, fontWeight: 600,
              boxShadow: '0 8px 24px rgba(91,124,250,0.25)',
            }}>
              <Icon name="add" size={20}/> Add family member
            </button>
          </div>
        ) : (
          <Card theme={theme} padding={0} style={{ overflow: 'hidden' }}>
            {fam.map((f, i) => (
