// Atoms.jsx — primitives shared across Lumio screens.
// Avatar, Icon (Lucide-style SVGs), Badge, presence dot, theme tokens.

const FL_TOKENS = {
  dark: {
    bg: '#1A2235', surface: '#222B42', surfaceLo: '#1F273C', surfaceHi: '#2A344E',
    hairline: '#37425E', hairlineStrong: '#4A5878',
    fg1: '#F2F4F8', fg2: '#9AA3B8', fg3: '#6E7895',
    innerGlow: 'inset 0 1px 0 rgba(255,255,255,.04)',
    scrim: 'rgba(10,16,30,.55)',
  },
  light: {
    bg: '#F4F6FB', surface: '#FFFFFF', surfaceLo: '#F8FAFE', surfaceHi: '#F0F3FA',
    hairline: '#E3E7F0', hairlineStrong: '#CDD4E1',
    fg1: '#1A2235', fg2: '#6B7488', fg3: '#9098A8',
    innerGlow: 'inset 0 -1px 0 rgba(26,34,53,.02)',
    scrim: 'rgba(26,34,53,.35)',
  },
};
const FL_ACCENT = { primary: '#5B7CFA', danger: '#FF6B6B', success: '#34C77B' };
const FL_AVATAR_TINTS = ['#6A7AA8', '#8B7AA8', '#A87A8B', '#7AA89E', '#A89B7A'];

function useT(theme) { return FL_TOKENS[theme]; }

function tintFor(seed) {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) | 0;
  return FL_AVATAR_TINTS[Math.abs(h) % FL_AVATAR_TINTS.length];
}

function initials(name) {
  return name
    .replace(/^(Grandma|Grandpa|Aunt|Uncle|Dad|Mom|Cousin|Brother|Sister)\s+/i, '')
    .split(/\s+/).filter(Boolean).slice(0, 2)
    .map(w => w[0]?.toUpperCase() || '').join('');
}

