# ── HTTP — redirect everything to HTTPS (except ACME challenges) ────────────
server {
    listen 80;
    server_name lumin.tahseen.tech;

    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

# ── HTTPS ────────────────────────────────────────────────────────────────────
server {
    listen 443 ssl;
    http2  on;
    server_name lumin.tahseen.tech;

    ssl_certificate     /etc/letsencrypt/live/lumin.tahseen.tech/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/lumin.tahseen.tech/privkey.pem;

    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_ciphers         ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305;
    ssl_prefer_server_ciphers off;
    ssl_session_cache   shared:SSL:10m;
    ssl_session_timeout 1d;

    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains" always;

    # ACME challenge (in case of renewal while HTTPS is live)
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location = /health {
        proxy_pass       http://fastapi/health;
        proxy_set_header Host $host;
        access_log       off;
    }

    location /api/ {
        proxy_pass       http://fastapi/api/;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Signed media
    location /media/ {
        auth_request /api/media/auth;
        alias        /var/app-media/;
        gzip         off;
        add_header   Cache-Control "private, no-transform" always;
    }

    location = /api/media/auth {
        internal;
        proxy_pass              http://fastapi;
        proxy_pass_request_body off;
        proxy_set_header        Content-Length "";
        proxy_set_header        X-Original-URI    $request_uri;
        proxy_set_header        X-Forwarded-Proto $scheme;
    }

    # Signaling WebSocket
    location /signal {
        proxy_pass         http://signaling;
        proxy_http_version 1.1;
        proxy_set_header   Upgrade    $http_upgrade;
        proxy_set_header   Connection "upgrade";
        proxy_set_header   Host       $host;
        proxy_read_timeout 300s;
        gzip               off;
    }
}

