2	import 'dart:io';
3	import 'package:drift/drift.dart';
4	import 'package:flutter_riverpod/flutter_riverpod.dart';
5	import 'package:uuid/uuid.dart';
6	import '../../../core/config/app_config.dart';
7	import '../../../core/services/signaling_service.dart';
8	import '../../../core/services/sync_service.dart';
9	import '../../../core/storage/local_db.dart';
10	import '../../../features/auth/domain/auth_notifier.dart';
11	import '../../../features/auth/domain/auth_state.dart';
12	import '../../../shared/models/message.dart';
13	import '../../../shared/models/user.dart';
14	import '../data/message_local_dao.dart';
15	import '../data/message_repository.dart';
16	
17	const _uuid = Uuid();
18	
19	// ── Chat state ────────────────────────────────────────────────────────────────
20	
21	class ChatState {
22	  final List<Message> messages;
23	  final User? otherUser;
24	  final bool isLoadingOlder;
25	  final bool otherUserTyping;
26	  final bool hasOlderMessages;
27	  final String? oldestCursor;
28	
29	  const ChatState({
30	    this.messages = const [],
31	    this.otherUser,
32	    this.isLoadingOlder = false,
33	    this.otherUserTyping = false,
34	    this.hasOlderMessages = true,
35	    this.oldestCursor,
36	  });
37	
38	  ChatState copyWith({
39	    List<Message>? messages,
40	    User? otherUser,
41	    bool? isLoadingOlder,
42	    bool? otherUserTyping,
43	    bool? hasOlderMessages,
44	    String? oldestCursor,
45	  }) =>
46	      ChatState(
47	        messages: messages ?? this.messages,
48	        otherUser: otherUser ?? this.otherUser,
49	        isLoadingOlder: isLoadingOlder ?? this.isLoadingOlder,
50	        otherUserTyping: otherUserTyping ?? this.otherUserTyping,
51	        hasOlderMessages: hasOlderMessages ?? this.hasOlderMessages,
52	        oldestCursor: oldestCursor ?? this.oldestCursor,
53	      );
54	}
55	
56	// ── ChatNotifier ──────────────────────────────────────────────────────────────
57	
58	class ChatNotifier extends FamilyNotifier<ChatState, String> {
59	  String get _conversationId => arg;
60	
61	  StreamSubscription<List<Message>>? _dbSub;
62	  StreamSubscription<MessageNewEvent>? _msgNewSub;
63	  StreamSubscription<MessageAckEvent>? _msgAckSub;
64	  StreamSubscription<MessageDeletedEvent>? _msgDelSub;
65	  StreamSubscription<TypingEvent>? _typingSub;
66	  Timer? _typingStopTimer;
67	  bool _isTyping = false;
68	
69	  @override
70	  ChatState build(String conversationId) {
71	    ref.onDispose(() {
72	      _dbSub?.cancel();
73	      _msgNewSub?.cancel();
74	      _msgAckSub?.cancel();
75	      _msgDelSub?.cancel();
76	      _typingSub?.cancel();
77	      _typingStopTimer?.cancel();
78	    });
79	
80	    if (AppConfig.uiOnly) {
81	      // UI-only: use mock data from the existing chat_thread_notifier pattern.
82	      return const ChatState();
83	    }
84	
85	    _init();
86	    return const ChatState();
87	  }
88	
89	  Future<void> _init() async {
90	    final dao = ref.read(messageLocalDaoProvider);
91	    final db = ref.read(appDatabaseProvider);
92	
93	    // Load cached messages immediately.
94	    final cached = await dao.getMessages(_conversationId);
95	    state = state.copyWith(messages: cached);
96	
97	    // Load other-user profile.
98	    final convRows = await (db.select(db.conversationsTable)
99	          ..where((c) => c.id.equals(_conversationId)))
100	        .get();
101	    if (convRows.isNotEmpty) {
102	      final userRow = await db.usersDao.getById(convRows.first.otherUserId);
103	      if (userRow != null) {
104	        state = state.copyWith(
105	          otherUser: User(
106	            id: userRow.id,
107	            name: userRow.name,
108	            phone: userRow.phone,
109	            avatarUrl: userRow.avatarUrl,
110	            lastSeen: userRow.lastSeen,
111	            presence: PresenceStatus.values.firstWhere(
112	              (e) => e.name == userRow.presence,
113	              orElse: () => PresenceStatus.offline,
114	            ),
115	          ),
116	        );
117	      }
118	    }
119	
120	    // Watch Drift for any changes (including optimistic writes).
121	    _dbSub = dao.watchMessages(_conversationId).listen((msgs) {
122	      state = state.copyWith(messages: msgs);
123	    });
124	
125	    // Mark unread as read.
126	    final unread = cached
127	        .where((m) => m.status != MessageStatus.read &&
128	            m.senderId != _currentUserId)
129	        .map((m) => m.id)
130	        .toList();
131	    if (unread.isNotEmpty) {
132	      ref.read(messageRepositoryProvider).markRead(unread).ignore();
133	      dao.clearUnread(_conversationId);
134	    }
135	
136	    // Fetch missed messages from server.
137	    await ref.read(syncServiceProvider).fetchMissedMessages(_conversationId);
138	
139	    // Real-time events.
140	    _subscribeToSignaling();
141	
142	    // Wire up reconnect → sync.
143	    ref.read(signalingServiceProvider).onReconnect = () {
144	      ref.read(syncServiceProvider).syncAll(_conversationId);
145	    };
146	  }
147	
148	  String get _currentUserId {
149	    final auth = ref.read(authNotifierProvider);
150	    if (auth is AuthAuthenticated) return auth.me.id;
151	    return '';
152	  }
153	
154	  void _subscribeToSignaling() {
155	    final signaling = ref.read(signalingServiceProvider);
156	
157	    _msgNewSub = signaling.onMessageNew.listen((event) {
158	      final msg = Message.fromJson(event.json);
159	      if (msg.conversationId != _conversationId) return;
160	      // Dedup on id — upsert into Drift, which fires the watch.
161	      ref.read(messageLocalDaoProvider).upsertMessage(msg);
162	      // Send read receipt.
163	      if (msg.senderId != _currentUserId) {
164	        ref.read(messageRepositoryProvider).markRead([msg.id]).ignore();
165	      }
166	    });
167	
168	    _msgAckSub = signaling.onMessageAck.listen((event) {
169	      final status = MessageStatus.values.firstWhere(
170	        (e) => e.name == event.status,
171	        orElse: () => MessageStatus.delivered,
172	      );
173	      ref.read(messageLocalDaoProvider).updateStatus(event.messageId, status);
174	    });
175	
176	    _msgDelSub = signaling.onMessageDeleted.listen((event) {
177	      if (event.conversationId != _conversationId) return;
178	      ref.read(messageLocalDaoProvider).markDeleted(event.messageId);
179	    });
180	
181	    _typingSub = signaling.onTyping.listen((event) {
182	      if (event.conversationId != _conversationId) return;
183	      state = state.copyWith(otherUserTyping: event.isTyping);
184	    });
185	  }
186	
187	  // ── Send text ─────────────────────────────────────────────────────────────
188	
189	  Future<void> sendText(String content, {String? replyToId}) async {
190	    if (content.trim().isEmpty) return;
191	    _stopTyping();
192	
193	    final clientId = _uuid.v4();
194	    final now = DateTime.now();
195	    final optimistic = Message(
196	      id: clientId,
197	      conversationId: _conversationId,
198	      senderId: _currentUserId,
199	      type: MessageType.text,
200	      content: content.trim(),
201	      status: MessageStatus.sending,
202	      createdAt: now,
203	      replyToId: replyToId,
204	    );
205	
206	    // Write to Drift immediately → optimistic UI.
207	    await ref.read(messageLocalDaoProvider).upsertMessage(optimistic);
208	
209	    try {
210	      final result = await ref.read(messageRepositoryProvider).sendMessage(
211	            clientId: clientId,
212	            conversationId: _conversationId,
213	            type: MessageType.text,
214	            content: content.trim(),
215	            replyToId: replyToId,
216	          );
217	      // Server response may differ in status/timestamps.
218	      await ref.read(messageLocalDaoProvider).upsertMessage(result);
219	      await ref.read(messageLocalDaoProvider).markSynced(clientId);
220	    } catch (_) {
221	      // Mark as failed — user can retry via long-press.
222	      await ref.read(messageLocalDaoProvider).updateStatus(
223	            clientId,
224	            MessageStatus.failed,
225	          );
226	    }
227	  }
228	
229	  // ── Send media ────────────────────────────────────────────────────────────
230	
231	  Future<void> sendMedia(
232	    File file,
233	    MessageType type, {
234	    String? replyToId,
235	    void Function(int sent, int total)? onProgress,
236	  }) async {
237	    final clientId = _uuid.v4();
238	    final now = DateTime.now();
239	
240	    // Track in PendingMediaUploads so it survives app restart.
241	    final db = ref.read(appDatabaseProvider);
242	    final stat = await file.stat();
243	    await db.pendingMediaUploadsDao.upsert(PendingMediaUploadsTableCompanion(
244	      localId: Value(clientId),
245	      filePath: Value(file.path),
246	      type: Value(type.name),
247	      conversationId: Value(_conversationId),
248	      totalBytes: Value(stat.size),
249	    ));
250	
251	    final optimistic = Message(
252	      id: clientId,
253	      conversationId: _conversationId,
254	      senderId: _currentUserId,
255	      type: type,
256	      media: MediaAttachment(url: file.path), // local path for optimistic UI
257	      status: MessageStatus.sending,
258	      createdAt: now,
259	      replyToId: replyToId,
260	    );
261	    await ref.read(messageLocalDaoProvider).upsertMessage(optimistic);
262	
263	    try {
264	      final upload = await ref.read(messageRepositoryProvider).uploadMedia(
265	            file: file,
266	            type: type.name,
267	            onProgress: (sent, total) {
268	              onProgress?.call(sent, total);
269	              db.pendingMediaUploadsDao.upsert(
270	                PendingMediaUploadsTableCompanion(
271	                  localId: Value(clientId),
272	                  uploadedBytes: Value(sent),
273	                  status: const Value('uploading'),
274	                ),
275	              );
276	            },
277	          );
278	
279	      final result = await ref.read(messageRepositoryProvider).sendMessage(
280	            clientId: clientId,
281	            conversationId: _conversationId,
282	            type: type,
283	            mediaId: upload.mediaId,
284	            replyToId: replyToId,
285	          );
286	      await ref.read(messageLocalDaoProvider).upsertMessage(result);
287	      await ref.read(messageLocalDaoProvider).markSynced(clientId);
288	      await db.pendingMediaUploadsDao.markDone(clientId);
289	    } catch (_) {
290	      await ref.read(messageLocalDaoProvider).updateStatus(
291	            clientId,
292	            MessageStatus.failed,
293	          );
294	    }
295	  }
296	
297	  // ── Retry ─────────────────────────────────────────────────────────────────
298	
299	  Future<void> retryMessage(String messageId) async {
300	    final msgs = state.messages;
301	    final msg = msgs.where((m) => m.id == messageId).firstOrNull;
302	    if (msg == null) return;
303	
304	    await ref.read(messageLocalDaoProvider).updateStatus(
305	          messageId,
306	          MessageStatus.sending,
307	        );
308	
309	    try {
310	      final result = await ref.read(messageRepositoryProvider).sendMessage(
311	            clientId: messageId,
312	            conversationId: _conversationId,
313	            type: msg.type,
314	            content: msg.content,
315	            replyToId: msg.replyToId,
316	          );
317	      await ref.read(messageLocalDaoProvider).upsertMessage(result);
318	      await ref.read(messageLocalDaoProvider).markSynced(messageId);
319	    } catch (_) {
320	      await ref.read(messageLocalDaoProvider).updateStatus(
321	            messageId,
322	            MessageStatus.failed,
323	          );
324	    }
325	  }
326	
327	  // ── Delete ────────────────────────────────────────────────────────────────
328	
329	  Future<void> deleteMessage(String messageId) async {
330	    await ref.read(messageLocalDaoProvider).markDeleted(messageId);
331	    ref.read(messageRepositoryProvider).deleteMessage(messageId).ignore();
332	  }
333	
334	  // ── Pagination ────────────────────────────────────────────────────────────
335	
336	  Future<void> loadOlderMessages() async {
337	    if (state.isLoadingOlder || !state.hasOlderMessages) return;
338	    state = state.copyWith(isLoadingOlder: true);
339	
340	    try {
341	      final older = await ref.read(messageRepositoryProvider).fetchMessages(
342	            _conversationId,
343	            cursor: state.oldestCursor,
344	          );
345	      if (older.isEmpty) {
346	        state = state.copyWith(isLoadingOlder: false, hasOlderMessages: false);
347	        return;
348	      }
349	      for (final msg in older) {
350	        await ref.read(messageLocalDaoProvider).upsertMessage(msg);
351	      }
352	      state = state.copyWith(
353	        isLoadingOlder: false,
354	        oldestCursor: older.first.id,
355	      );
356	    } catch (_) {
357	      state = state.copyWith(isLoadingOlder: false);
358	    }
359	  }
360	
361	  // ── Typing ────────────────────────────────────────────────────────────────
362	
363	  void onUserTyping() {
364	    if (!_isTyping) {
365	      _isTyping = true;
366	      ref.read(signalingServiceProvider).emitTyping(
367	            isTyping: true,
368	            conversationId: _conversationId,
369	          );
370	    }
371	    _typingStopTimer?.cancel();
372	    _typingStopTimer = Timer(const Duration(seconds: 2), _stopTyping);
373	  }
374	
375	  void _stopTyping() {
376	    if (!_isTyping) return;
377	    _isTyping = false;
378	    _typingStopTimer?.cancel();
379	    ref.read(signalingServiceProvider).emitTyping(
380	          isTyping: false,
381	          conversationId: _conversationId,
382	        );
383	  }
384	}
385	
386	final chatProvider =
387	    NotifierProviderFamily<ChatNotifier, ChatState, String>(ChatNotifier.new);
