// ignore_for_file: invalid_use_of_protected_member
// Tests for ChatNotifier: optimistic send, failure path, socket dedup, and
// receipt-tick updates. All database operations use an in-memory Drift DB so
// nothing is written to disk.

import 'dart:async';

import 'package:dio/dio.dart';
import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_riverpod/legacy.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:flutter_app/core/services/signaling_service.dart';
import 'package:flutter_app/core/services/sync_service.dart';
import 'package:flutter_app/core/storage/local_db.dart';
import 'package:flutter_app/core/storage/secure_storage.dart';
import 'package:flutter_app/features/auth/data/auth_repository.dart';
import 'package:flutter_app/features/auth/domain/auth_notifier.dart';
import 'package:flutter_app/features/auth/domain/auth_state.dart';
import 'package:flutter_app/features/chat/data/message_local_dao.dart';
import 'package:flutter_app/features/chat/data/message_repository.dart';
import 'package:flutter_app/features/chat/domain/chat_notifier.dart';
import 'package:flutter_app/shared/models/message.dart';

// ── Test fixtures ─────────────────────────────────────────────────────────────

const _convId = 'conv-test-001';
const _userId = 'user-me-001';
const _otherId = 'user-other-001';

// ── Fake: SecureStorageService ────────────────────────────────────────────────
// Overrides every method so FlutterSecureStorage (platform channel) is never
// called in the unit-test environment.

class _FakeSecureStorage extends SecureStorageService {
  @override
  Future<String?> readRefreshToken() async => null; // causes AuthUnauthenticated

  @override
  Future<void> saveRefreshToken(String token) async {}

  @override
  Future<void> deleteRefreshToken() async {}

  @override
  Future<String> readDeviceId() async => 'test-device-id';
}

// ── Fake: SignalingService ─────────────────────────────────────────────────────
// Replaces socket.io with local broadcast StreamControllers so tests can inject
// events directly.

class _FakeSignalingService extends SignalingService {
  final _newCtrl = StreamController<MessageNewEvent>.broadcast();
  final _ackCtrl = StreamController<MessageAckEvent>.broadcast();
  final _delCtrl = StreamController<MessageDeletedEvent>.broadcast();
  final _typCtrl = StreamController<TypingEvent>.broadcast();

  @override
  Stream<MessageNewEvent> get onMessageNew => _newCtrl.stream;
  @override
  Stream<MessageAckEvent> get onMessageAck => _ackCtrl.stream;
  @override
  Stream<MessageDeletedEvent> get onMessageDeleted => _delCtrl.stream;
  @override
  Stream<TypingEvent> get onTyping => _typCtrl.stream;

  @override
  void connect(String token) {}
  @override
  void emitTyping({required bool isTyping, required String conversationId}) {}
  @override
  void disconnect() {}

  @override
  void dispose() {
    // Close only our own controllers; do NOT call super.dispose() which would
    // close the parent's private controllers instead.
    _newCtrl.close();
    _ackCtrl.close();
    _delCtrl.close();
    _typCtrl.close();
  }

  void injectNew(MessageNewEvent e) => _newCtrl.add(e);
  void injectAck(MessageAckEvent e) => _ackCtrl.add(e);
}

// ── Fake: MessageRepository ────────────────────────────────────────────────────
// Lets tests hold the sendMessage Future open (to inspect mid-flight DB state)
// or make it throw immediately.

class _FakeMessageRepository extends MessageRepository {
  _FakeMessageRepository() : super(Dio());

  Completer<Message>? _sendHold;
  bool _throwNext = false;

  /// Makes the next [sendMessage] call block until [completeSend] is called.
  void holdNextSend() => _sendHold = Completer<Message>();

  /// Completes a previously held send with the supplied server response.
  void completeSend(Message response) {
    _sendHold!.complete(response);
    _sendHold = null;
  }

  /// Makes the next [sendMessage] call throw a network exception.
  void throwOnNextSend() => _throwNext = true;

  @override
  Future<Message> sendMessage({
    required String clientId,
    required String conversationId,
    required MessageType type,
    String? content,
    String? mediaId,
    String? replyToId,
  }) async {
    if (_throwNext) {
      _throwNext = false;
      throw Exception('network error');
    }
    if (_sendHold != null) return _sendHold!.future;
    return Message(
      id: clientId,
      conversationId: conversationId,
      senderId: _userId,
      type: type,
      content: content,
      status: MessageStatus.sent,
      createdAt: DateTime.now(),
    );
  }

  @override
  Future<void> markRead(List<String> ids) async {}
  @override
  Future<void> markDelivered(List<String> ids) async {}
  @override
  Future<List<Message>> fetchMessages(
    String conversationId, {
    String? cursor,
    int limit = 40,
  }) async =>
      [];
  @override
  Future<void> deleteMessage(String id) async {}
}

// ── Fake: SyncService ─────────────────────────────────────────────────────────

class _FakeSyncService extends SyncService {
  _FakeSyncService(AppDatabase db) : super(db, Dio());

  @override
  Future<void> syncPendingMessages() async {}
  @override
  Future<void> fetchMissedMessages(String id) async {}
  @override
  Future<void> syncConversations() async {}
  @override
  Future<void> syncAll(String id) async {}
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Flushes the Dart micro-task queue in several passes.  Since all Drift
/// operations on NativeDatabase.memory() are fast FFI calls, this is enough to
/// let chained await chains settle without any real-clock delay.
Future<void> _pump([int passes = 8]) async {
  for (var i = 0; i < passes; i++) {
    await Future<void>.delayed(Duration.zero);
  }
}

// ── Test suite ────────────────────────────────────────────────────────────────

void main() {
  late AppDatabase testDb;
  late _FakeSignalingService fakeSignaling;
  late _FakeMessageRepository fakeRepo;
  late ProviderContainer container;

  setUp(() async {
    testDb = AppDatabase.forTesting(NativeDatabase.memory());
    fakeSignaling = _FakeSignalingService();
    fakeRepo = _FakeMessageRepository();

    // Seed the conversation row so ChatNotifier._init() finds it in the DB.
    await testDb.conversationsDao.upsert(ConversationsTableCompanion(
      id: const Value(_convId),
      otherUserId: const Value(_otherId),
      lastActivity: Value(DateTime.now()),
    ));

    container = ProviderContainer(
      overrides: [
        // In-memory DB shared by the notifier and the DAO.
        appDatabaseProvider.overrideWithValue(testDb),
        // Fake signaling — no socket.io connection made.
        signalingServiceProvider.overrideWithValue(fakeSignaling),
        // Fake HTTP layer — no real network calls.
        messageRepositoryProvider.overrideWithValue(fakeRepo),
        // Fake sync — no-op so test setup doesn't trigger network.
        syncServiceProvider.overrideWith((ref) => _FakeSyncService(testDb)),
        // Auth deps — use fakes that don't touch platform channels.
        secureStorageProvider.overrideWithValue(_FakeSecureStorage()),
        authRepositoryProvider.overrideWith(
          (_) => AuthRepository(AppConfig.apiBaseUrl),
        ),
      ],
    );
  });

  tearDown(() async {
    container.dispose();
    fakeSignaling.dispose();
    await testDb.close();
  });

  // Convenience: builds the notifier and waits for _init() to settle.
  Future<ChatNotifier> buildNotifier() async {
    final notifier = container.read(chatProvider(_convId).notifier);
    await _pump(12); // let _init() async chain complete
    return notifier;
  }

  group('ChatNotifier', () {
    // ── 1 ─ Optimistic send ──────────────────────────────────────────────────

    test(
        'sendText writes optimistic "sending" row before network resolves, '
        'then promotes to "sent" after server responds', () async {
      final notifier = await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      // Hold the network call so we can inspect the intermediate DB state.
      fakeRepo.holdNextSend();

      // Fire-and-forget — the notifier suspends at the sendMessage await.
      final sendFuture = notifier.sendText('Hello world');
      await _pump(6); // flush until after the optimistic DB write

      // ── Before network resolves ──────────────────────────────────────────
      final msgsBeforeAck = await dao.getMessages(_convId);
      expect(msgsBeforeAck.length, 1,
          reason: 'optimistic row must be present immediately');
      expect(
        msgsBeforeAck.first.status,
        MessageStatus.sending,
        reason: 'status must be "sending" while network call is in-flight',
      );
      expect(msgsBeforeAck.first.content, 'Hello world');

      // ── After network resolves ────────────────────────────────────────────
      fakeRepo.completeSend(Message(
        id: msgsBeforeAck.first.id,
        conversationId: _convId,
        senderId: _userId,
        type: MessageType.text,
        content: 'Hello world',
        status: MessageStatus.sent,
        createdAt: msgsBeforeAck.first.createdAt,
      ));

      await sendFuture; // let sendText finish
      await _pump(6); // flush markSynced + watch notification

      final msgsAfterAck = await dao.getMessages(_convId);
      expect(
        msgsAfterAck.first.status,
        MessageStatus.sent,
        reason: 'status must be promoted to "sent" after server acknowledges',
      );
    });

    // ── 2 ─ Network failure ───────────────────────────────────────────────────

    test('network failure marks message as "failed" in the local DB', () async {
      final notifier = await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      fakeRepo.throwOnNextSend();

      await notifier.sendText('This will fail');
      await _pump(6);

      final msgs = await dao.getMessages(_convId);
      expect(msgs.length, 1);
      expect(
        msgs.first.status,
        MessageStatus.failed,
        reason: 'status must be "failed" when the network call throws',
      );
    });

    // ── 3 ─ Deduplication ─────────────────────────────────────────────────────

    test('duplicate message:new socket events do not create multiple DB rows',
        () async {
      await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      final msgJson = {
        'id': 'msg-dup-001',
        'conversation_id': _convId,
        'sender_id': _otherId,
        'type': 'text',
        'content': 'Duplicate delivery',
        'status': 'sent',
        'created_at': DateTime.now().toUtc().toIso8601String(),
        'is_deleted': false,
      };

      // Deliver the same event twice (simulates duplicate socket delivery).
      fakeSignaling.injectNew(MessageNewEvent(msgJson));
      fakeSignaling.injectNew(MessageNewEvent(msgJson));
      await _pump(12); // wait for both upsert calls

      final msgs = await dao.getMessages(_convId);
      final matches = msgs.where((m) => m.id == 'msg-dup-001').toList();
      expect(
        matches.length,
        1,
        reason: 'insertOnConflictUpdate must deduplicate on the "id" primary key',
      );
    });

    // ── 4 ─ Receipt ticks ─────────────────────────────────────────────────────

    test('message:ack event updates message status in the local DB', () async {
      await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      // Seed a previously sent message.
      await dao.upsertMessage(Message(
        id: 'msg-ack-001',
        conversationId: _convId,
        senderId: _userId,
        type: MessageType.text,
        content: 'Waiting for ack',
        status: MessageStatus.sent,
        createdAt: DateTime.now(),
      ));

      // Server sends back a "delivered" ack.
      fakeSignaling.injectAck(
        const MessageAckEvent(messageId: 'msg-ack-001', status: 'delivered'),
      );
      await _pump(12);

      final msgs = await dao.getMessages(_convId);
      final target = msgs.firstWhere((m) => m.id == 'msg-ack-001');
      expect(
        target.status,
        MessageStatus.delivered,
        reason: 'message:ack must promote status from "sent" to "delivered"',
      );
    });
  });
}

// ── AppConfig stub ────────────────────────────────────────────────────────────
// Re-export AppConfig so we can reference AppConfig.apiBaseUrl in overrides
// without a separate import (the real file already declares it).

class AppConfig {
  static String get apiBaseUrl =>
      const String.fromEnvironment('API_BASE_URL',
          defaultValue: 'http://localhost:8000');
}

