import 'dart:io';
import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import '../../../../core/theme/app_colors.dart';
import '../../../../shared/models/message.dart';
import 'voice_note_recorder.dart';

class ChatInputBar extends StatefulWidget {
  final TextEditingController controller;
  final FocusNode focusNode;
  final VoidCallback onSend;
  final void Function(File, MessageType) onSendMedia;
  final void Function(File, int) onSendVoice;
  final VoidCallback onTyping;
  final Widget? replyPreview;

  const ChatInputBar({
    super.key,
    required this.controller,
    required this.focusNode,
    required this.onSend,
    required this.onSendMedia,
    required this.onSendVoice,
    required this.onTyping,
    this.replyPreview,
  });

  @override
  State<ChatInputBar> createState() => _ChatInputBarState();
}

class _ChatInputBarState extends State<ChatInputBar> {
  bool _hasText = false;

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(() {
      final v = widget.controller.text.trim().isNotEmpty;
      if (v != _hasText) setState(() => _hasText = v);
      if (v) widget.onTyping();
    });
  }

  Future<void> _pickImage(ImageSource source) async {
    final img = await ImagePicker().pickImage(source: source, imageQuality: 85);
    if (img == null) return;
    widget.onSendMedia(File(img.path), MessageType.image);
  }

  Future<void> _pickVideo() async {
    final vid = await ImagePicker().pickVideo(source: ImageSource.gallery);
    if (vid == null) return;
    widget.onSendMedia(File(vid.path), MessageType.video);
  }

  Future<void> _pickFile() async {
    final result = await FilePicker.platform.pickFiles();
    if (result == null || result.files.single.path == null) return;
    widget.onSendMedia(File(result.files.single.path!), MessageType.file);
  }

  void _showAttachMenu() {
    showModalBottomSheet<void>(
      context: context,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (_) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 8),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              ListTile(
                leading: const Icon(Icons.photo_library_rounded,
                    color: AppColors.primary),
                title: const Text('Photo from gallery'),
                onTap: () {
                  Navigator.pop(context);
                  _pickImage(ImageSource.gallery);
                },
              ),
              ListTile(
                leading: const Icon(Icons.camera_alt_rounded,
                    color: AppColors.primary),
                title: const Text('Take photo'),
                onTap: () {
                  Navigator.pop(context);
                  _pickImage(ImageSource.camera);
                },
              ),
              ListTile(
                leading: const Icon(Icons.videocam_rounded,
                    color: AppColors.primary),
                title: const Text('Video'),
                onTap: () {
                  Navigator.pop(context);
                  _pickVideo();
                },
              ),
              ListTile(
                leading: const Icon(Icons.attach_file_rounded,
                    color: AppColors.primary),
                title: const Text('Document'),
                onTap: () {
                  Navigator.pop(context);
                  _pickFile();
                },
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final surface = isDark ? AppColors.darkSurface : AppColors.lightSurface;
    final fg3 = isDark ? AppColors.darkFg3 : AppColors.lightFg2;

    return Container(
      color: isDark ? AppColors.darkBg : AppColors.lightBg,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (widget.replyPreview != null) widget.replyPreview!,
          Padding(
            padding: EdgeInsets.fromLTRB(
              8,
              6,
              8,
              MediaQuery.viewInsetsOf(context).bottom > 0 ? 6 : 12,
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                // Attach button
                _IconBtn(
                  icon: Icons.add_rounded,
                  color: fg3,
                  onTap: _showAttachMenu,
                ),
                const SizedBox(width: 6),
                // Text field
                Expanded(
                  child: Container(
                    constraints: const BoxConstraints(maxHeight: 120),
                    decoration: BoxDecoration(
                      color: surface,
                      borderRadius: BorderRadius.circular(24),
                    ),
                    child: TextField(
                      controller: widget.controller,
                      focusNode: widget.focusNode,
                      minLines: 1,
                      maxLines: 5,
                      textCapitalization: TextCapitalization.sentences,
                      style: const TextStyle(fontSize: 15),
                      decoration: InputDecoration(
                        hintText: 'Message…',
                        hintStyle: TextStyle(color: fg3),
                        contentPadding: const EdgeInsets.symmetric(
                            horizontal: 16, vertical: 10),
                        border: InputBorder.none,
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 6),
                // Send / mic
                if (_hasText)
                  _SendButton(onTap: widget.onSend)
                else
                  VoiceNoteRecorder(
                    onSend: widget.onSendVoice,
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _IconBtn extends StatelessWidget {
  final IconData icon;
  final Color color;
  final VoidCallback onTap;
  const _IconBtn(
      {required this.icon, required this.color, required this.onTap});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: SizedBox(
        width: 40,
        height: 40,
        child: Icon(icon, color: color, size: 22),
      ),
    );
  }
}

class _SendButton extends StatelessWidget {
  final VoidCallback onTap;
  const _SendButton({required this.onTap});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        width: 44,
        height: 44,
        decoration: const BoxDecoration(
          color: AppColors.primary,
          shape: BoxShape.circle,
        ),
        child: const Icon(Icons.send_rounded, color: Colors.white, size: 20),
      ),
    );
  }
}

// Tests for SyncService:
//   1. syncPendingMessages sends messages in oldest-first order
//   2. successfully sent messages are marked isSynced=true in the DB
//   3. messages whose POST fails are left as unsynced for the next retry
//
// All Drift I/O uses an in-memory NativeDatabase — nothing is written to disk.
// HTTP calls are intercepted by a Dio interceptor — no real server needed.

import 'package:dio/dio.dart';
import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:flutter_app/core/services/sync_service.dart';
import 'package:flutter_app/core/storage/local_db.dart';

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Seeds one pending (un-synced) text message into [db].
Future<void> _seedPending(
  AppDatabase db, {
  required String id,
  required DateTime createdAt,
}) =>
    db.messagesDao.upsert(MessagesTableCompanion(
      id: Value(id),
      conversationId: const Value('conv-sync-001'),
      senderId: const Value('user-001'),
      messageType: const Value('text'),
      content: Value('Content of $id'),
      status: const Value('sending'),
      createdAt: Value(createdAt),
      isSynced: const Value(false),
      isDeleted: const Value(false),
    ));

/// Creates a [Dio] instance whose interceptor calls [onRequest] for every
/// outgoing request and immediately resolves it with an empty 200 response.
/// [onRequest] receives the [RequestOptions] so callers can record call order.
Dio _fakeDio({required void Function(RequestOptions opts) onRequest}) {
  final dio = Dio();
  dio.interceptors.add(
    InterceptorsWrapper(
      onRequest: (options, handler) {
        onRequest(options);
        handler.resolve(Response<Map<String, dynamic>>(
          requestOptions: options,
          statusCode: 200,
          data: <String, dynamic>{},
        ));
      },
    ),
  );
  return dio;
}

/// Creates a [Dio] instance that rejects every request with a timeout error.
Dio _failingDio() {
  final dio = Dio();
  dio.interceptors.add(
    InterceptorsWrapper(
      onRequest: (options, handler) {
        handler.reject(DioException(
          requestOptions: options,
          type: DioExceptionType.connectionTimeout,
          message: 'simulated timeout',
        ));
      },
    ),
  );
  return dio;
}

// ── Tests ─────────────────────────────────────────────────────────────────────

void main() {
  late AppDatabase db;

  setUp(() {
    db = AppDatabase.forTesting(NativeDatabase.memory());
  });

  tearDown(() async {
    await db.close();
  });

  group('SyncService.syncPendingMessages —', () {
    // ── 1. Ordering ───────────────────────────────────────────────────────────

    test(
        'sends messages in oldest-first order regardless of insertion order',
        () async {
      // Insert in reverse-chronological order to stress-test the sort.
      final t1 = DateTime.utc(2024, 1, 1, 10, 0); // oldest
      final t2 = DateTime.utc(2024, 1, 1, 11, 0);
      final t3 = DateTime.utc(2024, 1, 1, 12, 0); // newest

      await _seedPending(db, id: 'msg-3', createdAt: t3); // inserted first
      await _seedPending(db, id: 'msg-1', createdAt: t1);
      await _seedPending(db, id: 'msg-2', createdAt: t2);

      final sentIds = <String>[];
      final service = SyncService(
        db,
        _fakeDio(onRequest: (opts) {
          if (opts.method == 'POST') {
            final data = opts.data as Map<String, dynamic>;
            sentIds.add(data['id'] as String);
          }
        }),
      );

      await service.syncPendingMessages();

      expect(
        sentIds,
        ['msg-1', 'msg-2', 'msg-3'],
        reason: 'messages must be delivered to the server in chronological order '
            'so the server reconstructs the correct conversation sequence',
      );
    });

    // ── 2. Success → isSynced = true ──────────────────────────────────────────

    test(
        'marks a successfully sent message as isSynced=true and status="sent"',
        () async {
      await _seedPending(
        db,
        id: 'msg-sync-ok',
        createdAt: DateTime.utc(2024),
      );

      final service = SyncService(db, _fakeDio(onRequest: (_) {}));
      await service.syncPendingMessages();

      final rows = await (db.select(db.messagesTable)
            ..where((m) => m.id.equals('msg-sync-ok')))
          .get();

      expect(rows, hasLength(1));
      expect(rows.first.isSynced, isTrue,
          reason: 'row must be marked isSynced=true after a successful POST');
      expect(rows.first.status, 'sent',
          reason: 'status must be promoted to "sent"');
    });

    // ── 3. Failure → stays unsynced ───────────────────────────────────────────

    test(
        'leaves a message unsynced when the server call fails '
        '(error is swallowed; row is retried on next reconnect)',
        () async {
      await _seedPending(
        db,
        id: 'msg-sync-fail',
        createdAt: DateTime.utc(2024),
      );

      final service = SyncService(db, _failingDio());

      // syncPendingMessages must not throw — errors are swallowed per the impl.
      await expectLater(service.syncPendingMessages(), completes);

      final rows = await (db.select(db.messagesTable)
            ..where((m) => m.id.equals('msg-sync-fail')))
          .get();

      expect(rows.first.isSynced, isFalse,
          reason: 'row must remain unsynced so it is retried on the next call');
      expect(rows.first.status, 'sending',
          reason: 'status must not change when the POST fails');
    });

    // ── 4. Empty outbox → no requests ─────────────────────────────────────────

    test('makes no HTTP calls when the outbox is empty', () async {
      var callCount = 0;
      final service = SyncService(
        db,
        _fakeDio(onRequest: (_) => callCount++),
      );

      await service.syncPendingMessages();

      expect(callCount, 0,
          reason: 'no POST should be made when there are no pending messages');
    });
  });
}

// Tests for ChatNotifier:
//   1. optimistic send writes a "sending" row before the network resolves
//   2. network failure marks the row "failed"
//   3. duplicate message:new events are deduped by primary key
//   4. message:ack events update the stored status (receipt ticks)
//
// All Drift I/O uses an in-memory NativeDatabase — nothing is written to disk.

import 'dart:async';

import 'package:dio/dio.dart';
import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:flutter_app/core/config/app_config.dart';
import 'package:flutter_app/core/services/signaling_service.dart';
import 'package:flutter_app/core/services/sync_service.dart';
import 'package:flutter_app/core/storage/local_db.dart';
import 'package:flutter_app/core/storage/secure_storage.dart';
import 'package:flutter_app/features/auth/data/auth_repository.dart';
import 'package:flutter_app/features/chat/data/message_local_dao.dart';
import 'package:flutter_app/features/chat/data/message_repository.dart';
import 'package:flutter_app/features/chat/domain/chat_notifier.dart';
import 'package:flutter_app/shared/models/message.dart';

// ── Test constants ────────────────────────────────────────────────────────────

const _convId = 'conv-test-001';
const _userId = 'user-me-001';
const _otherId = 'user-other-001';

// ── Fake: SecureStorageService ────────────────────────────────────────────────
// Overrides every method so FlutterSecureStorage (a platform channel) is never
// called in the unit-test environment.

class _FakeSecureStorage extends SecureStorageService {
  @override
  Future<String?> readRefreshToken() async => null; // → AuthUnauthenticated

  @override
  Future<void> saveRefreshToken(String token) async {}

  @override
  Future<void> deleteRefreshToken() async {}

  @override
  Future<String> readDeviceId() async => 'test-device-id';
}

// ── Fake: SignalingService ────────────────────────────────────────────────────
// Replaces the socket.io connection with local StreamControllers so tests can
// push events directly without a running server.

class _FakeSignalingService extends SignalingService {
  final _newCtrl = StreamController<MessageNewEvent>.broadcast();
  final _ackCtrl = StreamController<MessageAckEvent>.broadcast();
  final _delCtrl = StreamController<MessageDeletedEvent>.broadcast();
  final _typCtrl = StreamController<TypingEvent>.broadcast();

  @override
  Stream<MessageNewEvent> get onMessageNew => _newCtrl.stream;
  @override
  Stream<MessageAckEvent> get onMessageAck => _ackCtrl.stream;
  @override
  Stream<MessageDeletedEvent> get onMessageDeleted => _delCtrl.stream;
  @override
  Stream<TypingEvent> get onTyping => _typCtrl.stream;

  @override
  void connect(String token) {}
  @override
  void emitTyping({required bool isTyping, required String conversationId}) {}
  @override
  void disconnect() {}

  @override
  void dispose() {
    // Close only our controllers — do NOT call super.dispose() which would
    // try to close the parent's private controllers.
    _newCtrl.close();
    _ackCtrl.close();
    _delCtrl.close();
    _typCtrl.close();
  }

  void injectNew(MessageNewEvent e) => _newCtrl.add(e);
  void injectAck(MessageAckEvent e) => _ackCtrl.add(e);
}

// ── Fake: MessageRepository ───────────────────────────────────────────────────
// Lets each test either block the sendMessage call (to inspect mid-flight DB
// state) or make it throw immediately.

class _FakeMessageRepository extends MessageRepository {
  _FakeMessageRepository() : super(Dio());

  Completer<Message>? _sendHold;
  bool _throwNext = false;

  /// Makes the next [sendMessage] hang until [completeSend] is called.
  void holdNextSend() => _sendHold = Completer<Message>();

  /// Unblocks a previously held send with the given server response.
  void completeSend(Message response) {
    _sendHold!.complete(response);
    _sendHold = null;
  }

  /// Makes the next [sendMessage] throw a network exception.
  void throwOnNextSend() => _throwNext = true;

  @override
  Future<Message> sendMessage({
    required String clientId,
    required String conversationId,
    required MessageType type,
    String? content,
    String? mediaId,
    String? replyToId,
  }) async {
    if (_throwNext) {
      _throwNext = false;
      throw Exception('simulated network error');
    }
    if (_sendHold != null) return _sendHold!.future;
    return Message(
      id: clientId,
      conversationId: conversationId,
      senderId: _userId,
      type: type,
      content: content,
      status: MessageStatus.sent,
      createdAt: DateTime.now(),
    );
  }

  @override
  Future<void> markRead(List<String> ids) async {}
  @override
  Future<void> markDelivered(List<String> ids) async {}
  @override
  Future<List<Message>> fetchMessages(
    String conversationId, {
    String? cursor,
    int limit = 40,
  }) async =>
      [];
  @override
  Future<void> deleteMessage(String id) async {}
}

// ── Fake: SyncService ─────────────────────────────────────────────────────────
// All methods are no-ops so test setup does not trigger any network calls.

class _FakeSyncService extends SyncService {
  _FakeSyncService(AppDatabase db) : super(db, Dio());

  @override
  Future<void> syncPendingMessages() async {}
  @override
  Future<void> fetchMissedMessages(String id) async {}
  @override
  Future<void> syncConversations() async {}
  @override
  Future<void> syncAll(String id) async {}
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Flushes the microtask queue in multiple passes.
/// NativeDatabase.memory() uses synchronous FFI calls, so a handful of
/// Future.delayed(Duration.zero) round-trips is enough for async chains to
/// propagate through all chained awaits.
Future<void> _pump([int passes = 8]) async {
  for (var i = 0; i < passes; i++) {
    await Future<void>.delayed(Duration.zero);
  }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

void main() {
  late AppDatabase testDb;
  late _FakeSignalingService fakeSignaling;
  late _FakeMessageRepository fakeRepo;
  late ProviderContainer container;

  setUp(() async {
    testDb = AppDatabase.forTesting(NativeDatabase.memory());
    fakeSignaling = _FakeSignalingService();
    fakeRepo = _FakeMessageRepository();

    // Seed the conversation row so ChatNotifier._init() finds it.
    await testDb.conversationsDao.upsert(ConversationsTableCompanion(
      id: const Value(_convId),
      otherUserId: const Value(_otherId),
      lastActivity: Value(DateTime.now()),
    ));

    container = ProviderContainer(
      overrides: [
        // Shared in-memory DB — used by the notifier, DAO provider, and fakes.
        appDatabaseProvider.overrideWithValue(testDb),
        // No socket.io: push events via injectNew / injectAck.
        signalingServiceProvider.overrideWithValue(fakeSignaling),
        // Controlled HTTP: block or fail individual calls.
        messageRepositoryProvider.overrideWithValue(fakeRepo),
        // Sync is a no-op — avoids network calls during init.
        syncServiceProvider.overrideWith((ref) => _FakeSyncService(testDb)),
        // Replace platform-channel storage with in-memory stubs.
        secureStorageProvider.overrideWithValue(_FakeSecureStorage()),
        // AuthRepository needs only a base URL — it will never be called since
        // _FakeSecureStorage returns null for the refresh token, causing
        // _tryRestoreSession to exit early (AuthUnauthenticated).
        authRepositoryProvider.overrideWith(
          (_) => AuthRepository(AppConfig.apiBaseUrl),
        ),
      ],
    );
  });

  tearDown(() async {
    container.dispose(); // cancels notifier subscriptions before we close streams
    fakeSignaling.dispose();
    await testDb.close();
  });

  /// Builds the ChatNotifier for [_convId] and waits for _init() to settle.
  Future<ChatNotifier> buildNotifier() async {
    final notifier = container.read(chatProvider(_convId).notifier);
    await _pump(12);
    return notifier;
  }

  group('ChatNotifier —', () {
    // ── 1. Optimistic send ────────────────────────────────────────────────────

    test(
        'sendText writes a "sending" row immediately, '
        'then promotes it to "sent" once the server responds', () async {
      final notifier = await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      // Block the network call so we can inspect the mid-flight DB state.
      fakeRepo.holdNextSend();

      // Start the send without awaiting.
      final sendFuture = notifier.sendText('Hello world');
      await _pump(6); // flush until after the optimistic upsert completes

      // ── Before server ack ─────────────────────────────────────────────────
      final preAck = await dao.getMessages(_convId);
      expect(preAck, hasLength(1),
          reason: 'optimistic row must be in the DB immediately');
      expect(preAck.first.status, MessageStatus.sending,
          reason: 'status must be "sending" while network call is in-flight');
      expect(preAck.first.content, 'Hello world');

      // ── After server ack ──────────────────────────────────────────────────
      fakeRepo.completeSend(Message(
        id: preAck.first.id,
        conversationId: _convId,
        senderId: _userId,
        type: MessageType.text,
        content: 'Hello world',
        status: MessageStatus.sent,
        createdAt: preAck.first.createdAt,
      ));

      await sendFuture;
      await _pump(6); // flush markSynced + Drift watch notification

      final postAck = await dao.getMessages(_convId);
      expect(postAck.first.status, MessageStatus.sent,
          reason: 'status must be promoted to "sent" after server ack');
    });

    // ── 2. Network failure ────────────────────────────────────────────────────

    test('network failure marks the row "failed" in the local DB', () async {
      final notifier = await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      fakeRepo.throwOnNextSend();

      await notifier.sendText('This will fail');
      await _pump(6);

      final msgs = await dao.getMessages(_convId);
      expect(msgs, hasLength(1));
      expect(msgs.first.status, MessageStatus.failed,
          reason: '"failed" status must be set when sendMessage throws');
    });

    // ── 3. Socket dedup ───────────────────────────────────────────────────────

    test(
        'injecting the same message:new event twice does not create duplicate '
        'rows (insertOnConflictUpdate deduplicates on the id primary key)',
        () async {
      await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      final msgJson = {
        'id': 'msg-dup-001',
        'conversation_id': _convId,
        'sender_id': _otherId,
        'type': 'text',
        'content': 'Hello from the other side',
        'status': 'sent',
        'created_at': DateTime.now().toUtc().toIso8601String(),
        'is_deleted': false,
      };

      fakeSignaling.injectNew(MessageNewEvent(msgJson));
      fakeSignaling.injectNew(MessageNewEvent(msgJson)); // duplicate delivery
      await _pump(12);

      final msgs = await dao.getMessages(_convId);
      expect(
        msgs.where((m) => m.id == 'msg-dup-001'),
        hasLength(1),
        reason: 'only one row must exist after two upserts with the same id',
      );
    });

    // ── 4. Receipt ticks ──────────────────────────────────────────────────────

    test('message:ack event updates the stored status from "sent" to "delivered"',
        () async {
      await buildNotifier();
      final dao = container.read(messageLocalDaoProvider);

      // Pre-seed a sent message.
      await dao.upsertMessage(Message(
        id: 'msg-ack-001',
        conversationId: _convId,
        senderId: _userId,
        type: MessageType.text,
        content: 'Waiting for receipt',
        status: MessageStatus.sent,
        createdAt: DateTime.now(),
      ));

      // Inject the "delivered" receipt from the server.
      fakeSignaling.injectAck(
        const MessageAckEvent(messageId: 'msg-ack-001', status: 'delivered'),
      );
      await _pump(12);

      final msgs = await dao.getMessages(_convId);
      final target = msgs.firstWhere((m) => m.id == 'msg-ack-001');
      expect(
        target.status,
        MessageStatus.delivered,
        reason: 'message:ack must tick the status to "delivered"',
      );
    });
  });
}

import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

part 'local_db.g.dart';

// ── Tables ────────────────────────────────────────────────────────────────────

@DataClassName('MessageRow')
class MessagesTable extends Table {
  TextColumn get id => text()();
  TextColumn get conversationId => text()();
  TextColumn get senderId => text()();
  TextColumn get messageType => text()(); // mirrors MessageType.name
  TextColumn get content => text().nullable()();
  TextColumn get mediaLocalPath => text().nullable()();
  TextColumn get mediaRemoteUrl => text().nullable()();
  TextColumn get thumbnailUrl => text().nullable()();
  TextColumn get status => text().withDefault(const Constant('sent'))();
  TextColumn get replyToId => text().nullable()();
  DateTimeColumn get createdAt => dateTime()();
  BoolColumn get isSynced =>
      boolean().withDefault(const Constant(false))();
  BoolColumn get isDeleted =>
      boolean().withDefault(const Constant(false))();

  @override
  Set<Column> get primaryKey => {id};
}

@DataClassName('ConversationRow')
class ConversationsTable extends Table {
  TextColumn get id => text()();
  TextColumn get otherUserId => text()();
  TextColumn get lastMessageId => text().nullable()();
  DateTimeColumn get lastActivity => dateTime()();
  IntColumn get unreadCount =>
      integer().withDefault(const Constant(0))();

  @override
  Set<Column> get primaryKey => {id};
}

@DataClassName('UserRow')
class UsersTable extends Table {
  TextColumn get id => text()();
  TextColumn get name => text()();
  TextColumn get phone => text()();
  TextColumn get avatarUrl => text().nullable()();
  DateTimeColumn get lastSeen => dateTime()();
  TextColumn get presence =>
      text().withDefault(const Constant('offline'))();

  @override
  Set<Column> get primaryKey => {id};
}

@DataClassName('CallRecordRow')
class CallRecordsTable extends Table {
  TextColumn get id => text()();
  TextColumn get otherUserId => text()();
  TextColumn get callType => text()();
  TextColumn get status => text()();
  DateTimeColumn get startedAt => dateTime()();
  IntColumn get durationSeconds => integer().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}

// Used by prompt 13 for resumable media uploads.
@DataClassName('PendingMediaUploadRow')
class PendingMediaUploadsTable extends Table {
  TextColumn get localId => text()();
  TextColumn get filePath => text()();
  TextColumn get type => text()(); // image | video | audio | file
  TextColumn get conversationId => text()();
  IntColumn get uploadedBytes =>
      integer().withDefault(const Constant(0))();
  IntColumn get totalBytes => integer()();
  TextColumn get status =>
      text().withDefault(const Constant('pending'))(); // pending | uploading | done | failed

  @override
  Set<Column> get primaryKey => {localId};
}

// ── DAOs ──────────────────────────────────────────────────────────────────────

@DriftAccessor(tables: [MessagesTable])
class MessagesDao extends DatabaseAccessor<AppDatabase>
    with _$MessagesDaoMixin {
  MessagesDao(super.db);

  Future<List<MessageRow>> getByConversation(String conversationId) =>
      (select(messagesTable)
            ..where((m) => m.conversationId.equals(conversationId))
            ..orderBy([(m) => OrderingTerm(expression: m.createdAt)]))
          .get();

  Stream<List<MessageRow>> watchByConversation(String conversationId) =>
      (select(messagesTable)
            ..where((m) => m.conversationId.equals(conversationId))
            ..orderBy([(m) => OrderingTerm(expression: m.createdAt)]))
          .watch();

  // Idempotent on id — safe to call for duplicate deliveries.
  Future<void> upsert(MessagesTableCompanion entry) =>
      into(messagesTable).insertOnConflictUpdate(entry);

  Future<void> markDeleted(String id) =>
      (update(messagesTable)..where((m) => m.id.equals(id)))
          .write(const MessagesTableCompanion(isDeleted: Value(true)));
}

@DriftAccessor(tables: [ConversationsTable])
class ConversationsDao extends DatabaseAccessor<AppDatabase>
    with _$ConversationsDaoMixin {
  ConversationsDao(super.db);

  Stream<List<ConversationRow>> watchAll() =>
      (select(conversationsTable)
            ..orderBy([
              (c) => OrderingTerm(
                    expression: c.lastActivity,
                    mode: OrderingMode.desc,
                  ),
            ]))
          .watch();

  Future<void> upsert(ConversationsTableCompanion entry) =>
      into(conversationsTable).insertOnConflictUpdate(entry);
}

@DriftAccessor(tables: [UsersTable])
class UsersDao extends DatabaseAccessor<AppDatabase> with _$UsersDaoMixin {
  UsersDao(super.db);

  Future<UserRow?> getById(String id) =>
      (select(usersTable)..where((u) => u.id.equals(id))).getSingleOrNull();

  Future<void> upsert(UsersTableCompanion entry) =>
      into(usersTable).insertOnConflictUpdate(entry);
}

@DriftAccessor(tables: [CallRecordsTable])
class CallRecordsDao extends DatabaseAccessor<AppDatabase>
    with _$CallRecordsDaoMixin {
  CallRecordsDao(super.db);

  Stream<List<CallRecordRow>> watchAll() =>
      (select(callRecordsTable)
            ..orderBy([
              (c) => OrderingTerm(
                    expression: c.startedAt,
                    mode: OrderingMode.desc,
                  ),
            ]))
          .watch();

  Future<void> upsert(CallRecordsTableCompanion entry) =>
      into(callRecordsTable).insertOnConflictUpdate(entry);
}

@DriftAccessor(tables: [PendingMediaUploadsTable])
class PendingMediaUploadsDao extends DatabaseAccessor<AppDatabase>
    with _$PendingMediaUploadsDaoMixin {
  PendingMediaUploadsDao(super.db);

  Future<List<PendingMediaUploadRow>> getPending() =>
      (select(pendingMediaUploadsTable)
            ..where((u) => u.status.isIn(['pending', 'uploading'])))
          .get();

  Future<void> upsert(PendingMediaUploadsTableCompanion entry) =>
      into(pendingMediaUploadsTable).insertOnConflictUpdate(entry);

  Future<void> markDone(String localId) =>
      (update(pendingMediaUploadsTable)
            ..where((u) => u.localId.equals(localId)))
          .write(
        const PendingMediaUploadsTableCompanion(status: Value('done')),
      );
}

// ── Database ──────────────────────────────────────────────────────────────────

@DriftDatabase(
  tables: [
    MessagesTable,
    ConversationsTable,
    UsersTable,
    CallRecordsTable,
    PendingMediaUploadsTable,
  ],
  daos: [
    MessagesDao,
    ConversationsDao,
    UsersDao,
    CallRecordsDao,
    PendingMediaUploadsDao,
  ],
)
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(_openConnection());

  /// Opens an in-memory database — used exclusively in unit tests.
  ///
  /// ```dart
  /// import 'package:drift/native.dart';
  /// final db = AppDatabase.forTesting(NativeDatabase.memory());
  /// ```
  AppDatabase.forTesting(QueryExecutor e) : super(e);

  @override
  int get schemaVersion => 1;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        onCreate: (m) => m.createAll(),
        beforeOpen: (_) async {
          // WAL mode improves concurrent read performance.
          await customStatement('PRAGMA journal_mode=WAL');
        },
      );
}

QueryExecutor _openConnection() => driftDatabase(name: 'lumin_db');

final appDatabaseProvider = Provider<AppDatabase>((ref) {
  final db = AppDatabase();
  ref.onDispose(db.close);
  return db;
});

