26	// ── Router ────────────────────────────────────────────────────────────────────
27	
28	final _routerRefreshProvider = Provider<GoRouterRefreshNotifier>((ref) {
29	  final notifier = GoRouterRefreshNotifier();
30	  ref.listen(authNotifierProvider, (_, next) => notifier.notify());
31	  ref.onDispose(notifier.dispose);
32	  return notifier;
33	});
34	
35	class GoRouterRefreshNotifier extends ChangeNotifier {
36	  void notify() => notifyListeners();
37	}
38	
39	final _routerProvider = Provider<GoRouter>((ref) {
40	  final refresh = ref.watch(_routerRefreshProvider);
41	
42	  return GoRouter(
43	    initialLocation: AppConfig.uiOnly ? '/home' : '/splash',
44	    refreshListenable: refresh,
45	    redirect: (context, state) {
46	      final loc = state.matchedLocation;
47	      final authState = ref.read(authNotifierProvider);
48	
49	      return switch (authState) {
50	        AuthUnknown() => loc == '/splash' ? null : '/splash',
51	        AuthUnauthenticated() => switch (loc) {
52	            '/login' || '/register' => null,
53	            _ => '/login',
54	          },
55	        AuthOtpPending() => loc == '/otp' ? null : '/otp',
56	        AuthAuthenticated() => switch (loc) {
57	            '/login' || '/register' || '/otp' || '/splash' => '/home',
58	            _ => null,
59	          },
60	      };
61	    },
62	    routes: [
63	      GoRoute(path: '/splash', builder: (_, __) => const SplashScreen()),
64	      GoRoute(path: '/login', builder: (_, __) => const LoginScreen()),
65	      GoRoute(path: '/register', builder: (_, __) => const RegisterScreen()),
66	      GoRoute(path: '/otp', builder: (_, __) => const OtpScreen()),
67	      // ── Authenticated shell ─────────────────────────────────────────────
68	      GoRoute(path: '/home', builder: (_, __) => const ShellScreen()),
69	      GoRoute(
70	          path: '/contacts/add',
71	          builder: (_, __) => const AddContactScreen()),
72	      // ── Chat search (legacy mock, replaced in prompt 14) ────────────────
73	      GoRoute(
74	          path: '/chat/search', builder: (_, __) => const SearchScreen()),
75	      // ── Chat — uses new real ChatScreen ─────────────────────────────────
76	      GoRoute(
77	        path: '/chat/:conversationId',
78	        builder: (_, state) => ChatScreen(
79	          conversationId: state.pathParameters['conversationId'] ?? '',
80	          contactName: state.uri.queryParameters['name'],
81	        ),
82	      ),
83	      // ── Media viewer — new full-screen viewer with photo_view / video ────
84	      GoRoute(
85	        path: '/media',
86	        builder: (_, state) {
87	          final kind = state.uri.queryParameters['kind'] ?? 'image';
88	          final url = state.uri.queryParameters['url'];
89	          if (url != null && (kind == 'image' || kind == 'video')) {
90	            return MediaViewerScreen(
91	              url: url,
92	              kind: kind,
93	              sender: state.uri.queryParameters['sender'],
94	              when: state.uri.queryParameters['when'],
95	            );
96	          }
97	          // Fallback to legacy placeholder for document / audio.
98	          return MediaViewerScreen(
99	            url: url ?? '',
100	            kind: kind,
101	            sender: state.uri.queryParameters['sender'],
102	            when: state.uri.queryParameters['when'],
103	          );
104	        },
105	      ),
106	      // ── Calls ────────────────────────────────────────────────────────────
107	      GoRoute(
108	        path: '/call/incoming',
109	        builder: (_, state) => IncomingCallScreen(
110	          name: state.uri.queryParameters['name'] ?? 'Family',
111	          kind: state.uri.queryParameters['kind'] ?? 'video',
112	        ),
113	      ),
114	      GoRoute(
115	        path: '/call/outgoing',
116	        builder: (_, state) => OutgoingCallScreen(
117	          name: state.uri.queryParameters['name'] ?? 'Family',
118	          kind: state.uri.queryParameters['kind'] ?? 'video',
119	        ),
120	      ),
121	      GoRoute(
122	        path: '/call/active',
123	        builder: (_, state) => ActiveCallScreen(
124	          name: state.uri.queryParameters['name'] ?? 'Family',
125	          kind: state.uri.queryParameters['kind'] ?? 'video',
126	        ),
127	      ),
