1	import 'dart:io';
2	import 'package:flutter/material.dart';
3	import 'package:flutter_riverpod/flutter_riverpod.dart';
4	import 'package:go_router/go_router.dart';
5	import 'package:intl/intl.dart';
6	import '../../../core/theme/app_colors.dart';
7	import '../../../features/auth/domain/auth_notifier.dart';
8	import '../../../features/auth/domain/auth_state.dart';
9	import '../../../shared/models/message.dart';
10	import '../../../shared/models/user.dart';
11	import '../../../shared/widgets/avatar.dart';
12	import '../domain/chat_notifier.dart';
13	import '../domain/presence_provider.dart';
14	import 'widgets/chat_input_bar.dart';
15	import 'widgets/message_bubble.dart';
16	import 'widgets/typing_indicator.dart';
17	
18	class ChatScreen extends ConsumerStatefulWidget {
19	  final String conversationId;
20	  final String? contactName;
21	
22	  const ChatScreen({
23	    super.key,
24	    required this.conversationId,
25	    this.contactName,
26	  });
27	
28	  @override
29	  ConsumerState<ChatScreen> createState() => _ChatScreenState();
30	}
31	
32	class _ChatScreenState extends ConsumerState<ChatScreen> {
33	  final _inputCtrl = TextEditingController();
34	  final _scrollCtrl = ScrollController();
35	  final _inputFocus = FocusNode();
36	  Message? _replyingTo;
37	
38	  @override
39	  void initState() {
40	    super.initState();
41	    WidgetsBinding.instance.addPostFrameCallback((_) => _scrollToBottom());
42	  }
43	
44	  @override
45	  void dispose() {
46	    _inputCtrl.dispose();
47	    _scrollCtrl.dispose();
48	    _inputFocus.dispose();
49	    super.dispose();
50	  }
51	
52	  void _scrollToBottom({bool animated = false}) {
53	    if (!_scrollCtrl.hasClients) return;
54	    final target = _scrollCtrl.position.maxScrollExtent;
55	    if (animated) {
56	      _scrollCtrl.animateTo(
57	        target,
58	        duration: const Duration(milliseconds: 300),
59	        curve: Curves.easeOut,
60	      );
61	    } else {
62	      _scrollCtrl.jumpTo(target);
63	    }
64	  }
65	
66	  String get _currentUserId {
67	    final auth = ref.read(authNotifierProvider);
68	    return auth is AuthAuthenticated ? auth.me.id : '';
69	  }
70	
71	  @override
72	  Widget build(BuildContext context) {
73	    final chatState = ref.watch(chatProvider(widget.conversationId));
74	    final notifier = ref.read(chatProvider(widget.conversationId).notifier);
75	    final isDark = Theme.of(context).brightness == Brightness.dark;
76	
77	    final otherUser = chatState.otherUser;
78	    final presenceAsync =
79	        ref.watch(presenceProvider(otherUser?.id ?? widget.conversationId));
80	    final isOnline = presenceAsync.valueOrNull == PresenceStatus.online;
81	
82	    // Scroll to bottom when new message arrives.
83	    ref.listen(chatProvider(widget.conversationId), (prev, next) {
84	      if ((prev?.messages.length ?? 0) < next.messages.length) {
85	        WidgetsBinding.instance
86	            .addPostFrameCallback((_) => _scrollToBottom(animated: true));
87	      }
88	    });
89	
90	    return Scaffold(
91	      appBar: _buildAppBar(context, otherUser, isOnline, isDark),
92	      body: Column(
93	        children: [
94	          // ── Message list ──────────────────────────────────────────────────
95	          Expanded(
96	            child: NotificationListener<ScrollNotification>(
97	              onNotification: (n) {
98	                if (n is ScrollStartNotification &&
99	                    _scrollCtrl.position.pixels == 0) {
100	                  notifier.loadOlderMessages();
101	                }
102	                return false;
103	              },
104	              child: ListView.builder(
105	                controller: _scrollCtrl,
106	                padding: const EdgeInsets.symmetric(
107	                    horizontal: 12, vertical: 12),
108	                itemCount: chatState.messages.length +
109	                    (chatState.isLoadingOlder ? 1 : 0) +
110	                    (chatState.otherUserTyping ? 1 : 0),
111	                itemBuilder: (_, i) {
112	                  if (chatState.isLoadingOlder && i == 0) {
113	                    return const Padding(
114	                      padding: EdgeInsets.only(bottom: 8),
115	                      child: Center(
116	                        child: SizedBox(
117	                          width: 20,
118	                          height: 20,
119	                          child: CircularProgressIndicator(strokeWidth: 2),
120	                        ),
121	                      ),
122	                    );
123	                  }
124	                  final offset = chatState.isLoadingOlder ? 1 : 0;
125	                  final msgs = chatState.messages;
126	
127	                  // Typing indicator at bottom
128	                  if (chatState.otherUserTyping &&
129	                      i == msgs.length + offset) {
130	                    return Padding(
131	                      padding: const EdgeInsets.only(top: 4),
132	                      child: Align(
133	                        alignment: Alignment.centerLeft,
134	                        child: Padding(
135	                          padding: const EdgeInsets.only(left: 4),
136	                          child: const TypingIndicator(),
137	                        ),
138	                      ),
139	                    );
140	                  }
141	
142	                  final msg = msgs[i - offset];
143	                  final isSent = msg.senderId == _currentUserId;
144	
145	                  return Padding(
146	                    padding: const EdgeInsets.only(bottom: 4),
147	                    child: Column(
148	                      crossAxisAlignment: CrossAxisAlignment.stretch,
149	                      children: [
150	                        if (_showDateSeparator(msgs, i - offset))
151	                          _DateSeparator(date: msg.createdAt),
152	                        MessageBubble(
153	                          message: msg,
154	                          isSent: isSent,
155	                          onReply: (_) =>
156	                              setState(() => _replyingTo = msg),
157	                          onDelete: isSent
158	                              ? (id) => notifier.deleteMessage(id)
159	                              : null,
160	                          onRetry: msg.status == MessageStatus.failed
161	                              ? (id) => notifier.retryMessage(id)
162	                              : null,
163	                        ),
164	                      ],
165	                    ),
166	                  );
167	                },
168	              ),
169	            ),
170	          ),
171	          // ── Reply preview ─────────────────────────────────────────────────
172	          // ── Input bar ─────────────────────────────────────────────────────
173	          ChatInputBar(
174	            controller: _inputCtrl,
175	            focusNode: _inputFocus,
176	            onSend: () {
177	              final text = _inputCtrl.text;
178	              if (text.trim().isEmpty) return;
179	              _inputCtrl.clear();
180	              notifier.sendText(text, replyToId: _replyingTo?.id);
181	              setState(() => _replyingTo = null);
182	            },
183	            onSendMedia: (File file, MessageType type) =>
