1	import 'dart:async';
2	import 'package:flutter/foundation.dart';
3	import 'package:flutter_riverpod/flutter_riverpod.dart';
4	import 'package:socket_io_client/socket_io_client.dart' as sio;
5	import '../auth/auth_token.dart';
6	import '../config/app_config.dart';
7	
8	// ── Event payloads ────────────────────────────────────────────────────────────
9	
10	class MessageNewEvent {
11	  final Map<String, dynamic> json;
12	  const MessageNewEvent(this.json);
13	}
14	
15	class MessageAckEvent {
16	  final String messageId;
17	  final String status; // 'delivered' | 'read'
18	  const MessageAckEvent({required this.messageId, required this.status});
19	}
20	
21	class MessageDeletedEvent {
22	  final String messageId;
23	  final String conversationId;
24	  const MessageDeletedEvent(
25	      {required this.messageId, required this.conversationId});
26	}
27	
28	class TypingEvent {
29	  final String fromUserId;
30	  final String conversationId;
31	  final bool isTyping;
32	  const TypingEvent(
33	      {required this.fromUserId,
34	      required this.conversationId,
35	      required this.isTyping});
36	}
37	
38	class PresenceEvent {
39	  final String userId;
40	  final String status; // 'online' | 'offline'
41	  final DateTime? lastSeen;
42	  const PresenceEvent(
43	      {required this.userId, required this.status, this.lastSeen});
44	}
45	
46	// Call events — consumed by prompt 14
47	class CallIncomingEvent {
48	  final Map<String, dynamic> json;
49	  const CallIncomingEvent(this.json);
50	}
51	
52	// ── SignalingService ──────────────────────────────────────────────────────────
53	
54	class SignalingService {
55	  sio.Socket? _socket;
56	
57	  final _messageNewCtrl =
58	      StreamController<MessageNewEvent>.broadcast();
59	  final _messageAckCtrl =
60	      StreamController<MessageAckEvent>.broadcast();
61	  final _messageDeletedCtrl =
62	      StreamController<MessageDeletedEvent>.broadcast();
63	  final _typingCtrl = StreamController<TypingEvent>.broadcast();
64	  final _presenceCtrl = StreamController<PresenceEvent>.broadcast();
65	  final _callIncomingCtrl =
66	      StreamController<CallIncomingEvent>.broadcast();
67	
68	  Stream<MessageNewEvent> get onMessageNew => _messageNewCtrl.stream;
69	  Stream<MessageAckEvent> get onMessageAck => _messageAckCtrl.stream;
70	  Stream<MessageDeletedEvent> get onMessageDeleted =>
71	      _messageDeletedCtrl.stream;
72	  Stream<TypingEvent> get onTyping => _typingCtrl.stream;
73	  Stream<PresenceEvent> get onPresence => _presenceCtrl.stream;
74	  Stream<CallIncomingEvent> get onCallIncoming => _callIncomingCtrl.stream;
75	
76	  /// Fired on connect / reconnect — SyncService subscribes to this.
77	  VoidCallback? onReconnect;
78	
79	  bool get isConnected => _socket?.connected ?? false;
80	
81	  void connect(String accessToken) {
82	    _socket?.dispose();
83	    _socket = sio.io(
84	      AppConfig.signalingUrl,
85	      sio.OptionBuilder()
86	          .setPath('/signal')
87	          .setTransports(['websocket'])
88	          .setAuth({'token': accessToken})
89	          .enableReconnection()
90	          .setReconnectionAttempts(99999)
91	          .setReconnectionDelay(1000)
92	          .setReconnectionDelayMax(10000)
93	          .setRandomizationFactor(0.5)
94	          .setTimeout(20000)
95	          .disableAutoConnect()
96	          .build(),
97	    );
98	    _attachListeners();
99	    _socket!.connect();
100	  }
101	
102	  /// Call after a token refresh so the next reconnect uses the fresh token.
103	  void updateToken(String accessToken) {
104	    _socket?.auth = {'token': accessToken};
105	  }
106	
107	  void _attachListeners() {
108	    final s = _socket!;
109	
110	    s.on('connect', (_) => onReconnect?.call());
111	    s.on('reconnect', (_) => onReconnect?.call());
112	
113	    s.on('message:new', (data) {
114	      final map = _asMap(data);
115	      if (map != null) _messageNewCtrl.add(MessageNewEvent(map));
116	    });
117	
118	    s.on('message:ack', (data) {
119	      final map = _asMap(data);
120	      if (map != null) {
121	        _messageAckCtrl.add(MessageAckEvent(
122	          messageId: map['message_id'] as String,
123	          status: map['status'] as String,
124	        ));
125	      }
126	    });
127	
128	    s.on('message:deleted', (data) {
129	      final map = _asMap(data);
130	      if (map != null) {
131	        _messageDeletedCtrl.add(MessageDeletedEvent(
132	          messageId: map['message_id'] as String,
133	          conversationId: map['conversation_id'] as String,
134	        ));
135	      }
136	    });
137	
138	    s.on('typing:start', (data) {
139	      final map = _asMap(data);
140	      if (map != null) {
141	        _typingCtrl.add(TypingEvent(
142	          fromUserId: map['from'] as String,
143	          conversationId: map['conversation_id'] as String,
144	          isTyping: true,
145	        ));
146	      }
147	    });
148	
149	    s.on('typing:stop', (data) {
150	      final map = _asMap(data);
151	      if (map != null) {
152	        _typingCtrl.add(TypingEvent(
153	          fromUserId: map['from'] as String,
154	          conversationId: map['conversation_id'] as String,
155	          isTyping: false,
156	        ));
157	      }
158	    });
159	
160	    s.on('presence:update', (data) {
161	      final map = _asMap(data);
162	      if (map != null) {
163	        _presenceCtrl.add(PresenceEvent(
164	          userId: map['user_id'] as String,
165	          status: map['status'] as String,
166	          lastSeen: map['last_seen'] != null
167	              ? DateTime.parse(map['last_seen'] as String)
