    if (danger) {
      bg = AppColors.danger;
      fg = Colors.white;
      border = Border.all(color: Colors.transparent);
    }

    return Column(
      children: [
        GestureDetector(
          onTap: onTap,
          child: Container(
            width: 60,
            height: 60,
            decoration: BoxDecoration(
              color: bg,
              border: border,
              shape: BoxShape.circle,
