              ),
              SizedBox(height: 4),
              Text(
                "We'll keep your call going.",
                style: TextStyle(
                  color: Colors.white70,
                  fontSize: 13,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _RemoteVideoFeedPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    // Fill Radial Gradient (Martinez Dad Mike remote feed mockup)
    final rect = Rect.fromLTWH(0, 0, size.width, size.height);
    final paint = Paint()
      ..shader = const RadialGradient(
        colors: [Color(0xFF5B7CFA), Color(0xFF222B42), Color(0xFF0B0F1A)],
        center: Alignment(0, -0.32),
        radius: 0.7,
      ).createShader(rect);
    canvas.drawRect(rect, paint);

    // Head silhouette
    final silhouettePaint = Paint()..color = const Color(0xFF1A2235).withValues(alpha: 0.65);
    canvas.drawCircle(Offset(size.width * 0.5, size.height * 0.43), 120, silhouettePaint);

    // Shoulders silhouette
    final shoulderPaint = Paint()..color = const Color(0xFF0F1525).withValues(alpha: 0.85);
    final path = Path()
      ..moveTo(size.width * 0.1, size.height)
      ..quadraticBezierTo(size.width * 0.1, size.height * 0.73, size.width * 0.5, size.height * 0.73)
      ..quadraticBezierTo(size.width * 0.9, size.height * 0.73, size.width * 0.9, size.height)
      ..close();
    canvas.drawPath(path, shoulderPaint);

    // Skin highlight
    final facePaint = Paint()..color = const Color(0xFF3D4C72).withValues(alpha: 0.55);
    canvas.drawOval(
      Rect.fromCenter(
        center: Offset(size.width * 0.44, size.height * 0.39),
        width: 120,
        height: 156,
      ),
      facePaint,
    );

    // Eyes
    final featurePaint = Paint()..color = const Color(0xFF0B0F1A);
    canvas.drawCircle(Offset(size.width * 0.46, size.height * 0.41), 3, featurePaint);
    canvas.drawCircle(Offset(size.width * 0.54, size.height * 0.42), 3, featurePaint);

    // Smile
    final linePaint = Paint()
      ..color = const Color(0xFF0B0F1A)
      ..strokeWidth = 2
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round;
    canvas.drawPath(
      Path()
        ..moveTo(size.width * 0.48, size.height * 0.47)
        ..quadraticBezierTo(size.width * 0.51, size.height * 0.49, size.width * 0.54, size.height * 0.48),
      linePaint,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class _LocalVideoFeedPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    // Fill Gradient
    final rect = Rect.fromLTWH(0, 0, size.width, size.height);
    final paint = Paint()
      ..shader = const LinearGradient(
        colors: [Color(0xFF7AA89E), Color(0xFF0F1525)],
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
      ).createShader(rect);
    canvas.drawRect(rect, paint);

    // Head silhouette
    final silhouettePaint = Paint()..color = const Color(0xFF0B0F1A).withValues(alpha: 0.7);
    canvas.drawCircle(Offset(size.width * 0.5, size.height * 0.43), 22, silhouettePaint);

    // Shoulder curve
    final shoulderPaint = Paint()..color = const Color(0xFF0B0F1A).withValues(alpha: 0.8);
    final path = Path()
      ..moveTo(size.width * 0.14, size.height)
      ..quadraticBezierTo(size.width * 0.14, size.height * 0.69, size.width * 0.5, size.height * 0.69)
      ..quadraticBezierTo(size.width * 0.86, size.height * 0.69, size.width * 0.86, size.height)
      ..close();
    canvas.drawPath(path, shoulderPaint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

import 'dart:io';
import 'package:dio/dio.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/network/dio_client.dart';
import '../../../shared/models/message.dart';

class MessageRepository {
  final Dio _dio;

  MessageRepository(this._dio);

  // ── Send ──────────────────────────────────────────────────────────────────

  Future<Message> sendMessage({
    required String clientId,
    required String conversationId,
    required MessageType type,
    String? content,
    String? mediaId,
    String? replyToId,
  }) async {
    final resp = await _dio.post<Map<String, dynamic>>(
      '/api/messages',
      data: {
        'id': clientId,
        'conversation_id': conversationId,
        'type': type.name,
        'content': ?content,
        'media_id': ?mediaId,
        'reply_to_id': ?replyToId,
      },
    );
    return Message.fromJson(resp.data!);
  }

  // ── Fetch ─────────────────────────────────────────────────────────────────

  Future<List<Message>> fetchMessages(
    String conversationId, {
    String? cursor,
    int limit = 40,
  }) async {
    final resp = await _dio.get<Map<String, dynamic>>(
      '/api/conversations/$conversationId/messages',
      queryParameters: {
        'limit': limit,
        'cursor': ?cursor,
      },
    );
    final items = (resp.data?['items'] as List<dynamic>?) ?? [];
    return items
        .map((e) => Message.fromJson(e as Map<String, dynamic>))
        .toList();
  }

  // ── Receipts ──────────────────────────────────────────────────────────────

  Future<void> markDelivered(List<String> messageIds) async {
    if (messageIds.isEmpty) return;
    await _dio.post<void>(
      '/api/messages/delivered',
      data: {'message_ids': messageIds},
    );
  }

  Future<void> markRead(List<String> messageIds) async {
    if (messageIds.isEmpty) return;
    await _dio.post<void>(
      '/api/messages/read',
      data: {'message_ids': messageIds},
    );
  }

  // ── Delete ────────────────────────────────────────────────────────────────

  Future<void> deleteMessage(String messageId) async {
    await _dio.delete<void>('/api/messages/$messageId');
  }

  // ── Media upload ──────────────────────────────────────────────────────────

  /// Uploads a file and returns the `media_id` + signed URLs.
  /// [onProgress] reports (sent, total) bytes for the progress indicator.
  Future<MediaUploadResult> uploadMedia({
    required File file,
    required String type, // 'image' | 'video' | 'audio' | 'file'
    void Function(int sent, int total)? onProgress,
    CancelToken? cancelToken,
  }) async {
    final formData = FormData.fromMap({
      'file': await MultipartFile.fromFile(
        file.path,
        filename: file.path.split(Platform.pathSeparator).last,
      ),
      'type': type,
    });

    final resp = await _dio.post<Map<String, dynamic>>(
      '/api/media/upload',
      data: formData,
      cancelToken: cancelToken,
      onSendProgress: onProgress,
    );
    return MediaUploadResult.fromJson(resp.data!);
  }
}

class MediaUploadResult {
  final String mediaId;
  final String url;
  final String? thumbnailUrl;
  final int? width;
  final int? height;
  final int? durationSeconds;

  const MediaUploadResult({
    required this.mediaId,
    required this.url,
    this.thumbnailUrl,
    this.width,
    this.height,
    this.durationSeconds,
  });

  factory MediaUploadResult.fromJson(Map<String, dynamic> json) =>
      MediaUploadResult(
        mediaId: json['media_id'] as String,
        url: json['url'] as String,
        thumbnailUrl: json['thumbnail_url'] as String?,
        width: json['width'] as int?,
        height: json['height'] as int?,
        durationSeconds: json['duration_seconds'] as int?,
      );

  MediaAttachment toAttachment() => MediaAttachment(
        url: url,
        thumbnailUrl: thumbnailUrl,
        width: width,
        height: height,
        durationSeconds: durationSeconds,
      );
}

final messageRepositoryProvider = Provider<MessageRepository>((ref) {
  return MessageRepository(ref.watch(dioProvider));
});

import 'package:flutter/material.dart';
import 'package:flutter_sound/flutter_sound.dart';
import '../../../../core/theme/app_colors.dart';

class VoiceNotePlayer extends StatefulWidget {
  final String url;
  final int? durationSeconds;
  final bool isSent; // affects color scheme

  const VoiceNotePlayer({
    super.key,
    required this.url,
    this.durationSeconds,
    this.isSent = false,
  });

  @override
  State<VoiceNotePlayer> createState() => _VoiceNotePlayerState();
}

class _VoiceNotePlayerState extends State<VoiceNotePlayer> {
  final _player = FlutterSoundPlayer();
  bool _isPlaying = false;
  double _progress = 0;
  int _elapsed = 0;
  bool _initialized = false;

  @override
  void initState() {
    super.initState();
    _player.openPlayer().then((_) {
      if (mounted) setState(() => _initialized = true);
    });
  }

  @override
  void dispose() {
    _player.closePlayer();
    super.dispose();
  }

  Future<void> _toggle() async {
    if (!_initialized) return;
    if (_isPlaying) {
      await _player.pausePlayer();
      setState(() => _isPlaying = false);
    } else {
      await _player.startPlayer(
        fromURI: widget.url,
        whenFinished: () {
          if (mounted) {
            setState(() {
              _isPlaying = false;
              _progress = 0;
              _elapsed = 0;
            });
          }
        },
      );
      _player.onProgress!.listen((e) {
        if (!mounted) return;
        final total = e.duration.inMilliseconds;
        final pos = e.position.inMilliseconds;
        setState(() {
          _elapsed = e.position.inSeconds;
          _progress = total > 0 ? pos / total : 0;
        });
      });
      setState(() => _isPlaying = true);
    }
  }

  String _fmt(int seconds) {
    final m = seconds ~/ 60;
    final s = seconds % 60;
    return '$m:${s.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    final total = widget.durationSeconds ?? 0;
    final fg = widget.isSent ? Colors.white : AppColors.primary;
    final trackColor =
        widget.isSent ? Colors.white.withValues(alpha: 0.3) : AppColors.primary.withValues(alpha: 0.2);

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        GestureDetector(
          onTap: _toggle,
          child: Container(
            width: 36,
            height: 36,
            decoration: BoxDecoration(
              color: fg.withValues(alpha: 0.15),
              shape: BoxShape.circle,
            ),
            child: Icon(
              _isPlaying ? Icons.pause_rounded : Icons.play_arrow_rounded,
              color: fg,
              size: 20,
            ),
          ),
        ),
        const SizedBox(width: 8),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              ClipRRect(
                borderRadius: BorderRadius.circular(4),
                child: LinearProgressIndicator(
                  value: _progress,
                  backgroundColor: trackColor,
                  valueColor: AlwaysStoppedAnimation<Color>(fg),
                  minHeight: 3,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                '${_fmt(_elapsed)} / ${_fmt(total)}',
                style: TextStyle(
                  fontSize: 11,
                  color: fg.withValues(alpha: 0.7),
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

import 'dart:async';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:flutter_sound/flutter_sound.dart';
import 'package:path_provider/path_provider.dart';
import 'package:permission_handler/permission_handler.dart';
import '../../../../core/theme/app_colors.dart';

/// Hold-to-record mic button. Slide left to cancel. Releases with the
/// recorded file, or null if the user cancelled.
class VoiceNoteRecorder extends StatefulWidget {
  final void Function(File file, int durationSeconds) onSend;

  const VoiceNoteRecorder({super.key, required this.onSend});

  @override
  State<VoiceNoteRecorder> createState() => _VoiceNoteRecorderState();
}

class _VoiceNoteRecorderState extends State<VoiceNoteRecorder>
    with SingleTickerProviderStateMixin {
  final _recorder = FlutterSoundRecorder();
  bool _recording = false;
  bool _cancelled = false;
  int _seconds = 0;
  Timer? _timer;
  String? _filePath;
  late final AnimationController _pulseCtrl;
  double _dragX = 0;

  static const _cancelThreshold = -80.0;

  @override
  void initState() {
    super.initState();
    _pulseCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 800),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _pulseCtrl.dispose();
    _timer?.cancel();
    _recorder.closeRecorder();
    super.dispose();
  }

  Future<void> _startRecording() async {
    final perm = await Permission.microphone.request();
    if (!perm.isGranted) return;

    await _recorder.openRecorder();
    final dir = await getTemporaryDirectory();
    _filePath = '${dir.path}/voice_${DateTime.now().millisecondsSinceEpoch}.aac';

    await _recorder.startRecorder(toFile: _filePath);
    _seconds = 0;
    _cancelled = false;
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() => _seconds++);
    });
    setState(() => _recording = true);
  }

  Future<void> _stopRecording({bool cancel = false}) async {
    _timer?.cancel();
    await _recorder.stopRecorder();
    await _recorder.closeRecorder();

    if (!cancel && !_cancelled && _filePath != null && _seconds >= 1) {
      widget.onSend(File(_filePath!), _seconds);
    }
    setState(() {
      _recording = false;
      _dragX = 0;
    });
  }

  String _fmt(int s) {
    final m = s ~/ 60;
    final sec = s % 60;
    return '${m.toString().padLeft(2, '0')}:${sec.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    if (_recording) return _buildRecordingBar();
    return GestureDetector(
      onLongPressStart: (_) => _startRecording(),
      onLongPressEnd: (_) => _stopRecording(),
      onLongPressMoveUpdate: (d) {
        setState(() => _dragX = d.localPosition.dx);
        if (_dragX < _cancelThreshold && !_cancelled) {
          _cancelled = true;
          _stopRecording(cancel: true);
        }
      },
      child: Container(
        width: 44,
        height: 44,
        decoration: BoxDecoration(
          color: AppColors.primary.withValues(alpha: 0.1),
          shape: BoxShape.circle,
        ),
        child: const Icon(Icons.mic_rounded, color: AppColors.primary, size: 22),
      ),
    );
  }

  Widget _buildRecordingBar() {
    return AnimatedBuilder(
      animation: _pulseCtrl,
      builder: (_, _) => Container(
        height: 44,
        padding: const EdgeInsets.symmetric(horizontal: 16),
        decoration: BoxDecoration(
          color: AppColors.primary.withValues(alpha: 0.08 + _pulseCtrl.value * 0.06),
          borderRadius: BorderRadius.circular(22),
        ),
        child: Row(
          children: [
            Icon(Icons.mic_rounded,
                color: AppColors.danger.withValues(alpha: 0.8 + _pulseCtrl.value * 0.2),
                size: 20),
            const SizedBox(width: 8),
            Text(
              _fmt(_seconds),
              style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w600,
                  color: AppColors.danger),
            ),
            const Spacer(),
            const Text(
              '← slide to cancel',
              style: TextStyle(fontSize: 12, color: Colors.grey),
            ),
          ],
        ),
      ),
    );
  }
}

