  // ── Emit helpers ─────────────────────────────────────────────────────────

  void emitTyping({required bool isTyping, required String conversationId}) {
    _socket?.emit(
      isTyping ? 'typing:start' : 'typing:stop',
      {'conversation_id': conversationId},
    );
  }

  void emitPresence(String status) {
