  }

  void disconnect() => _socket?.disconnect();

  void dispose() {
    _socket?.dispose();
    _messageNewCtrl.close();
    _messageAckCtrl.close();
    _messageDeletedCtrl.close();
    _typingCtrl.close();
    _presenceCtrl.close();
    _callIncomingCtrl.close();
  }
}

final signalingServiceProvider = Provider<SignalingService>((ref) {
