    final session = state;
    if (session == null || _webrtc == null) {
      return;
    }
    try {
      final offer = payload['offer'] as Map<String, dynamic>? ?? {};
      final answer = await _webrtc!.createAnswer(
        offer,
        videoEnabled: session.callType == CallType.video,
      );
