                    alignment: Alignment.center,
                    children: [
                      ScaleTransition(
                        scale: Tween<double>(begin: 0.85, end: 1.15)
                            .animate(_ring1),
                        child: FadeTransition(
                          opacity:
                              Tween<double>(begin: 0.55, end: 0.0)
                                  .animate(_ring1),
                          child: Container(
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              border: Border.all(
                                  color: AppColors.primary,
                                  width: 1.5),
                            ),
                          ),
                        ),
                      ),
                      ScaleTransition(
                        scale: Tween<double>(begin: 0.85, end: 1.15)
                            .animate(_ring2),
                        child: FadeTransition(
                          opacity:
                              Tween<double>(begin: 0.55, end: 0.0)
                                  .animate(_ring2),
                          child: Container(
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
