1	import 'dart:async';
2	import 'package:flutter_riverpod/flutter_riverpod.dart';
3	import 'package:uuid/uuid.dart';
4	import 'package:wakelock_plus/wakelock_plus.dart';
5	import '../../../core/services/signaling_service.dart';
6	import '../../../core/services/webrtc_service.dart';
7	import '../data/call_repository.dart';
8	import 'call_state.dart';
9	
10	class CallNotifier extends Notifier<CallSession?> {
11	  WebRTCService? _webrtc;
12	
13	  // ── Timers ──────────────────────────────────────────────────────────────────
14	  Timer? _reconnectTimer;   // 3 s before entering reconnecting phase
15	  Timer? _failTimer;        // 30 s before giving up on reconnection
16	  Timer? _ringTimeoutTimer; // 45 s ring timeout (incoming or outgoing)
17	  Timer? _qualityTimer;     // 5 s quality poll
18	  Timer? _durationTimer;    // 1 s tick to update displayed duration
19	
20	  final List<StreamSubscription<dynamic>> _subs = [];
21	
22	  // ── Build ───────────────────────────────────────────────────────────────────
23	
24	  @override
25	  CallSession? build() {
26	    _subscribeToSignaling();
27	    ref.onDispose(_cleanup);
28	    return null;
29	  }
30	
31	  // ── Public interface ────────────────────────────────────────────────────────
32	
33	  /// Expose the live WebRTC service so screens can access renderers.
34	  WebRTCService? get webrtcService => _webrtc;
35	
36	  /// Place an outgoing call to [peer].
37	  Future<void> startCall(PeerUser peer, CallType callType) async {
38	    if (state != null) {
39	      return; // only one active call at a time
40	    }
41	
42	    final callId = const Uuid().v4();
43	
44	    state = CallSession(
45	      callId: callId,
46	      peerUser: peer,
47	      callType: callType,
48	      direction: CallDirection.outgoing,
49	      phase: CallPhase.outgoingRinging,
50	      startedAt: DateTime.now().toUtc(),
51	    );
52	
53	    try {
54	      final iceServers =
55	          await ref.read(callRepositoryProvider).getTurnCredentials();
56	
57	      _webrtc = createWebRTCService();
58	      await _webrtc!.initialize(iceServers: iceServers);
59	      _wireCallbacks(peer.id);
60	
61	      final offer =
62	          await _webrtc!.createOffer(videoEnabled: callType == CallType.video);
63	
64	      ref.read(signalingServiceProvider).emitCallInitiate(
65	            callId: callId,
66	            to: peer.id,
67	            offer: offer,
68	            callType: callType.name,
69	          );
70	
71	      // Cancel if no answer arrives within 45 s
72	      _ringTimeoutTimer = Timer(const Duration(seconds: 45), () {
73	        if (state?.phase == CallPhase.outgoingRinging) {
74	          _endWithReason(EndReason.timeout);
75	        }
76	      });
77	    } catch (_) {
78	      _endWithReason(EndReason.failed);
79	    }
80	  }
81	
82	  /// Called when a `call:incoming` socket event arrives (also from prompt 15).
83	  Future<void> handleIncomingCall(Map<String, dynamic> payload) async {
84	    if (state != null) {
85	      // Already in a call — tell the caller we're busy.
86	      ref.read(signalingServiceProvider).emitCallBusy(
87	            callId: payload['call_id'] as String? ?? '',
88	            to: payload['from'] as String? ?? '',
89	          );
90	      return;
91	    }
92	
93	    final fromUser =
94	        payload['from_user'] as Map<String, dynamic>? ?? const {};
95	    final peer = PeerUser.fromJson({
96	      'id': payload['from'] as String? ?? fromUser['id'] as String? ?? '',
97	      ...fromUser,
98	    });
99	
100	    final callType = (payload['call_type'] as String?) == 'video'
101	        ? CallType.video
102	        : CallType.audio;
103	
104	    state = CallSession(
105	      callId: payload['call_id'] as String? ?? const Uuid().v4(),
106	      peerUser: peer,
107	      callType: callType,
108	      direction: CallDirection.incoming,
109	      phase: CallPhase.incomingRinging,
110	      startedAt: DateTime.now().toUtc(),
111	      pendingOffer: payload['offer'] as Map<String, dynamic>?,
112	    );
113	
114	    // Missed-call timeout
115	    _ringTimeoutTimer = Timer(const Duration(seconds: 45), () {
116	      if (state?.phase == CallPhase.incomingRinging) {
117	        _endWithReason(EndReason.missed);
118	      }
119	    });
120	  }
121	
122	  /// Accept an incoming call (callee side).
123	  Future<void> acceptCall() async {
124	    final session = state;
125	    if (session == null || session.phase != CallPhase.incomingRinging) {
126	      return;
127	    }
128	
129	    _ringTimeoutTimer?.cancel();
130	    _ringTimeoutTimer = null;
131	    state = session.copyWith(phase: CallPhase.connecting);
132	
133	    try {
134	      final iceServers =
135	          await ref.read(callRepositoryProvider).getTurnCredentials();
136	
137	      _webrtc = createWebRTCService();
138	      await _webrtc!.initialize(iceServers: iceServers);
139	      _wireCallbacks(session.peerUser.id);
140	
141	      final offer = session.pendingOffer;
142	      if (offer == null) {
143	        _endWithReason(EndReason.failed);
144	        return;
145	      }
146	
147	      final answer = await _webrtc!.createAnswer(
148	        offer,
149	        videoEnabled: session.callType == CallType.video,
150	      );
151	
152	      ref.read(signalingServiceProvider).emitCallAnswer(
153	            callId: session.callId,
154	            to: session.peerUser.id,
155	            answer: answer,
156	          );
157	    } catch (_) {
158	      _endWithReason(EndReason.failed);
159	    }
160	  }
161	
162	  /// Decline an incoming call.
163	  void declineCall() {
164	    final session = state;
165	    if (session == null || session.phase != CallPhase.incomingRinging) {
166	      return;
167	    }
168	    ref.read(signalingServiceProvider).emitCallReject(
169	          callId: session.callId,
170	          to: session.peerUser.id,
171	        );
172	    _endWithReason(EndReason.rejected);
173	  }
174	
175	  /// Hang up the current call from any phase.
176	  Future<void> endCall() async {
177	    final session = state;
178	    if (session == null) {
179	      return;
180	    }
181	    if (session.phase != CallPhase.incomingRinging) {
182	      ref.read(signalingServiceProvider).emitCallHangup(
183	            callId: session.callId,
184	            to: session.peerUser.id,
185	          );
186	    }
187	    await _teardown();
188	    _endWithReason(EndReason.hungUp);
189	  }
190	
191	  // ── In-call controls ────────────────────────────────────────────────────────
192	
193	  Future<void> toggleMic() async {
194	    final session = state;
195	    if (session == null) {
196	      return;
197	    }
198	    await _webrtc?.toggleMic();
199	    state = session.copyWith(isMuted: !session.isMuted);
200	  }
201	
202	  Future<void> toggleCamera() async {
203	    final session = state;
204	    if (session == null) {
205	      return;
206	    }
207	    await _webrtc?.toggleCamera();
208	    state = session.copyWith(isCameraOff: !session.isCameraOff);
209	  }
210	
211	  Future<void> switchCamera() async {
212	    await _webrtc?.switchCamera();
213	  }
214	
215	  Future<void> toggleSpeaker() async {
216	    final session = state;
217	    if (session == null) {
218	      return;
219	    }
220	    final newVal = !session.isSpeakerOn;
221	    await _webrtc?.setSpeakerphone(newVal);
222	    state = session.copyWith(isSpeakerOn: newVal);
223	  }
224	
225	  /// Downgrade a video call to audio-only without dropping the call.
226	  Future<void> switchToAudioOnly() async {
227	    final session = state;
228	    if (session == null) {
229	      return;
230	    }
231	    await _webrtc?.toggleCamera(); // disables video track
232	    state = session.copyWith(
233	      isCameraOff: true,
234	      showSwitchToAudioPrompt: false,
235	      callType: CallType.audio,
236	    );
237	  }
238	
239	  void dismissSwitchToAudioPrompt() {
240	    final session = state;
241	    if (session != null) {
242	      state = session.copyWith(showSwitchToAudioPrompt: false);
243	    }
244	  }
245	
246	  // ── Overridable factory (swap in tests) ─────────────────────────────────────
247	
248	  /// Override in test subclasses to inject a mock WebRTCService.
249	  WebRTCService createWebRTCService() => WebRTCServiceImpl();
250	
251	  // ── Signaling subscriptions ─────────────────────────────────────────────────
252	
253	  void _subscribeToSignaling() {
254	    final sig = ref.read(signalingServiceProvider);
255	
256	    _subs.addAll([
257	      sig.onCallIncoming.listen((event) async {
258	        await handleIncomingCall(event.json);
259	      }),
260	      sig.onCallAnswered.listen((event) async {
261	        await _handleCallAnswered(event.json);
262	      }),
263	      sig.onCallIce.listen((event) async {
264	        await _handleRemoteIce(event.json);
265	      }),
266	      sig.onCallIceRestart.listen((event) async {
267	        await _handleIceRestartOffer(event.json);
268	      }),
269	      sig.onCallHangup.listen(_handleRemoteHangup),
270	      sig.onCallRejected.listen(_handleCallRejected),
271	      sig.onCallBusy.listen(_handleCallBusy),
272	      sig.onCallMissed.listen(_handleCallMissed),
273	    ]);
274	  }
275	
276	  // ── Signaling handlers ───────────────────────────────────────────────────────
277	
278	  Future<void> _handleCallAnswered(Map<String, dynamic> payload) async {
279	    final session = state;
280	    if (session == null || session.phase != CallPhase.outgoingRinging) {
281	      return;
282	    }
283	    _ringTimeoutTimer?.cancel();
284	    _ringTimeoutTimer = null;
285	
286	    state = session.copyWith(phase: CallPhase.connecting);
287	
288	    try {
289	      final answer =
290	          payload['answer'] as Map<String, dynamic>? ?? payload;
291	      await _webrtc?.setRemoteDescription(answer);
292	    } catch (_) {
293	      _endWithReason(EndReason.failed);
294	    }
295	  }
296	
297	  Future<void> _handleRemoteIce(Map<String, dynamic> payload) async {
298	    final candidate = payload['candidate'];
299	    if (candidate == null || _webrtc == null) {
300	      return;
301	    }
302	    try {
303	      await _webrtc!.addIceCandidate(
304	        candidate is Map<String, dynamic> ? candidate : {},
305	      );
306	    } catch (_) {}
307	  }
308	
309	  Future<void> _handleIceRestartOffer(Map<String, dynamic> payload) async {
310	    final session = state;
311	    if (session == null || _webrtc == null) {
312	      return;
313	    }
314	    try {
315	      final offer = payload['offer'] as Map<String, dynamic>? ?? {};
316	      final answer = await _webrtc!.createAnswer(
317	        offer,
318	        videoEnabled: session.callType == CallType.video,
319	      );
320	      ref.read(signalingServiceProvider).emitCallAnswer(
321	            callId: session.callId,
322	            to: session.peerUser.id,
323	            answer: answer,
324	          );
325	    } catch (_) {}
326	  }
327	
328	  void _handleRemoteHangup(CallHangupEvent event) {
329	    final session = state;
