4	// Channel IDs referenced by the native manifest and prompt 15 call service.
5	const kChannelMessages = 'messages';
6	const kChannelCalls = 'calls';
7	
8	class NotificationService {
9	  final FlutterLocalNotificationsPlugin _plugin =
10	      FlutterLocalNotificationsPlugin();
11	
12	  Future<void> init() async {
13	    const android = AndroidInitializationSettings('@mipmap/ic_launcher');
14	    await _plugin.initialize(settings: const InitializationSettings(android: android));
15	    await _createChannels();
16	  }
17	
