        return Intent(this, CallActionReceiver::class.java).apply {
            this.action = action
            putExtra(EXTRA_CALL_ID, callId)
            for (key in PAYLOAD_KEYS) {
                val v = sourceIntent.getStringExtra(key)
                if (v != null) putExtra(key, v)
            }
        }
