            wl.acquire(WAKE_LOCK_TIMEOUT_MS)
            wakeLock = wl
        } catch (t: Throwable) {
            Log.w(TAG, "wake lock failed: ${t.message}")
        }
    }

    private fun releaseWakeLock() {
        try {
            wakeLock?.let { if (it.isHeld) it.release() }
        } catch (_: Throwable) { /* ignore */ }
        wakeLock = null
    }

    // ── Timeout ─────────────────────────────────────────────────────────────────

    private fun armRingTimeout() {
