  test('emits call:busy when already in a call', () async {
    await notifier.handleIncomingCall(_incomingPayload);
    expect(sig.emittedEvents, isEmpty);

    await notifier.handleIncomingCall({
      ..._incomingPayload,
      'call_id': 'call-second-999',
