8	class CallRepository {
9	  final Dio _dio;
10	  final AppDatabase _db;
11	
12	  const CallRepository(this._dio, this._db);
13	
14	  // ── TURN credentials ────────────────────────────────────────────────────────
15	
16	  /// Fetch TURN/STUN credentials for a new call.
17	  /// Returns a list of ICE server config maps ready for `RTCPeerConnection`.
18	  Future<List<Map<String, dynamic>>> getTurnCredentials() async {
19	    try {
20	      final resp = await _dio
21	          .get<Map<String, dynamic>>('/api/auth/turn-credentials');
22	      final servers = resp.data?['ice_servers'] as List<dynamic>? ?? [];
23	      return servers
24	          .whereType<Map<String, dynamic>>()
25	          .toList();
26	    } catch (_) {
27	      // Fallback: public STUN only (no TURN relay)
28	      return [
29	        {'urls': 'stun:stun.l.google.com:19302'},
30	      ];
31	    }
32	  }
33	
34	  // ── Call history ─────────────────────────────────────────────────────────────
35	
36	  /// Fetch paginated call history from the API and write to Drift.
37	  Future<List<CallRecord>> getCallHistory({
38	    String? cursor,
39	    int limit = 30,
40	  }) async {
41	    final resp = await _dio.get<Map<String, dynamic>>(
42	      '/api/calls/history',
43	      queryParameters: {
44	        'limit': limit,
45	        'cursor': ?cursor,
46	      },
47	    );
48	    final items = (resp.data?['items'] as List<dynamic>?) ?? [];
49	    final records =
50	        items.map((e) => CallRecord.fromJson(e as Map<String, dynamic>)).toList();
51	
52	    // Cache to Drift (best-effort — ignore failures)
53	    for (final rec in records) {
54	      try {
55	        await _db.callRecordsDao.upsert(
56	          CallRecordsTableCompanion(
57	            id: Value(rec.id),
58	            otherUserId: Value(rec.peerUser.id),
59	            callType: Value(rec.callType.name),
60	            status: Value(
61	              '${rec.direction.name}_${rec.status}', // e.g. 'incoming_missed'
62	            ),
63	            startedAt: Value(rec.startedAt),
64	            durationSeconds: Value(rec.durationSeconds),
65	          ),
66	        );
67	      } catch (_) {}
68	    }
69	
70	    return records;
71	  }
72	
73	  /// Fetch a single call record.
74	  Future<CallRecord?> getCall(String callId) async {
75	    final resp =
76	        await _dio.get<Map<String, dynamic>>('/api/calls/$callId');
77	    if (resp.data == null) {
78	      return null;
79	    }
80	    return CallRecord.fromJson(resp.data!);
81	  }
82	
83	  /// Watch cached call records from Drift (offline-first).
84	  Stream<List<CallRecordRow>> watchCachedHistory() =>
85	      _db.callRecordsDao.watchAll();
86	}
87	
88	final callRepositoryProvider = Provider<CallRepository>((ref) {
89	  return CallRepository(
90	    ref.watch(dioProvider),
91	    ref.watch(appDatabaseProvider),
92	  );
93	});
