import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_riverpod/legacy.dart';
import '../../../core/auth/auth_token.dart';
import '../../../core/config/app_config.dart';
import '../../../core/mock/mock_data.dart';
import '../../../core/storage/secure_storage.dart';
import '../../../shared/models/user.dart';
import '../data/auth_repository.dart';
import 'auth_state.dart';

class AuthNotifier extends StateNotifier<AuthState> {
  final AuthRepository _repo;
  final SecureStorageService _secure;
  final Ref _ref;

  AuthNotifier(this._repo, this._secure, this._ref)
      : super(
          AppConfig.uiOnly
              ? AuthAuthenticated(me: MockData.currentUser)
              : const AuthUnknown(),
        ) {
    if (AppConfig.uiOnly) {
      // Defer — Riverpod forbids modifying another provider during init.
      Future.microtask(
        () => _ref.read(authTokenProvider.notifier).set('ui-only-token'),
      );
    } else {
      _tryRestoreSession();
    }
  }

  // ── Session restore ───────────────────────────────────────────────────────

  Future<void> _tryRestoreSession() async {
    // uiOnly is false here — constructor only calls this when !AppConfig.uiOnly.
    final savedRefresh = await _secure.readRefreshToken();
    if (savedRefresh == null) {
      state = const AuthUnauthenticated();
      return;
    }
    try {
      final deviceId = await _secure.readDeviceId();
      final tokens = await _repo.refreshAccessToken(
        refreshToken: savedRefresh,
        deviceId: deviceId,
      );
      _ref.read(authTokenProvider.notifier).set(tokens.accessToken);
      await _secure.saveRefreshToken(tokens.refreshToken);
      final me = await _repo.getMe(tokens.accessToken);
      state = AuthAuthenticated(me: me);
    } catch (_) {
      await _secure.deleteRefreshToken();
      _ref.read(authTokenProvider.notifier).clear();
      state = const AuthUnauthenticated();
    }
  }

  // ── Login ─────────────────────────────────────────────────────────────────

  /// Validates credentials and requests an OTP. Throws on failure so the
  /// screen can display a Snackbar without changing global auth state.
  /// Skips login/API and opens the main shell (UI-only mode).
  Future<void> signInDemo() async {
    _ref.read(authTokenProvider.notifier).set('ui-only-token');
    state = AuthAuthenticated(me: MockData.currentUser);
  }

  Future<void> requestLoginOtp({
    required String phone,
    required String password,
  }) async {
    if (AppConfig.uiOnly) {
      await signInDemo();
      return;
    }
    final result = await _repo.requestLoginOtp(
      phone: phone,
      password: password,
    );
    state = AuthOtpPending(phone: result.phone, debugOtp: result.debugOtp);
  }

  // ── Register ──────────────────────────────────────────────────────────────

  Future<void> register({
    required String name,
    required String phone,
    required String password,
  }) async {
    if (AppConfig.uiOnly) {
      _ref.read(authTokenProvider.notifier).set('ui-only-token');
      state = AuthAuthenticated(
        me: User(
          id: MockData.currentUser.id,
          name: name,
          phone: phone,
          lastSeen: DateTime.now(),
          presence: PresenceStatus.online,
        ),
      );
      return;
    }
    final result = await _repo.register(
      name: name,
      phone: phone,
      password: password,
    );
    state = AuthOtpPending(
      phone: result.phone,
      isRegistering: true,
      debugOtp: result.debugOtp,
    );
  }

  // ── OTP verification ──────────────────────────────────────────────────────

  /// Throws on wrong code so the OTP screen can shake the boxes.
  Future<void> verifyOtp({required String code}) async {
    if (AppConfig.uiOnly) {
      await signInDemo();
      return;
    }
    final pending = state as AuthOtpPending;
    final deviceId = await _secure.readDeviceId();
    final result = await _repo.verifyOtp(
      phone: pending.phone,
      code: code,
      deviceId: deviceId,
    );
    _ref.read(authTokenProvider.notifier).set(result.accessToken);
    await _secure.saveRefreshToken(result.refreshToken);
    state = AuthAuthenticated(me: result.me);
  }

  // ── Sign out ──────────────────────────────────────────────────────────────

  Future<void> signOut() async {
    if (AppConfig.uiOnly) {
      _ref.read(authTokenProvider.notifier).clear();
      state = const AuthUnauthenticated();
      return;
    }
    final token = _ref.read(authTokenProvider);
    if (token != null) {
      try {
        final deviceId = await _secure.readDeviceId();
        await _repo.logout(accessToken: token, deviceId: deviceId);
      } catch (_) {
        // Always clear locally, even if server call fails.
      }
    }
    _ref.read(authTokenProvider.notifier).clear();
    await _secure.deleteRefreshToken();
    state = const AuthUnauthenticated();
  }

  /// Called by the Dio interceptor when a token refresh fails mid-flight.
  /// Does NOT await async cleanup — it's fire-and-forget by design.
  void forceSignOut() {
    if (AppConfig.uiOnly) return;
    _ref.read(authTokenProvider.notifier).clear();
    state = const AuthUnauthenticated();
    // Delete the stale refresh token in the background.
    _secure.deleteRefreshToken();
  }

  // ── Profile sync ──────────────────────────────────────────────────────────

  /// Updates the cached User inside the Authenticated state, e.g. after name
  /// or avatar changes from ProfileScreen.
  void updateCachedUser(User user) {
    final current = state;
    if (current is AuthAuthenticated) {
      state = AuthAuthenticated(me: user);
    }
  }
}

final authNotifierProvider =
    StateNotifierProvider<AuthNotifier, AuthState>((ref) {
  return AuthNotifier(
    ref.watch(authRepositoryProvider),
    ref.watch(secureStorageProvider),
    ref,
  );
});

"""
Firebase Cloud Messaging service.

OAuth2 access tokens are cached in process memory and refreshed ~5 minutes
before expiry (tokens last ~1 hour). The lock is created lazily so it binds
to the running event loop — safe for both the FastAPI process and the worker.

send_fcm() result codes:
  success        — 200, notification delivered.
  token_invalid  — 404 / UNREGISTERED, token cleared from DB, no retry.
  retryable      — 429 / 5xx, caller should retry with backoff.
  failed         — other 4xx, permanent, logged, no retry.
"""
from __future__ import annotations

import asyncio
import logging
import time
from dataclasses import dataclass, field
from typing import Literal

import httpx
from sqlalchemy import select, update
from sqlalchemy.ext.asyncio import AsyncSession

from app.config import settings

logger = logging.getLogger(__name__)

FCM_SEND_URL = (
    "https://fcm.googleapis.com/v1/projects/{project_id}/messages:send"
)
FCM_SCOPES = ["https://www.googleapis.com/auth/firebase.messaging"]


# ── Token cache (process-local) ───────────────────────────────────────────────

_token_cache: dict = {"token": None, "expires_at": 0.0}
_token_lock: asyncio.Lock | None = None


async def _get_access_token() -> str:
    """
    Return a valid FCM OAuth2 access token, refreshing when within 5 min of expiry.
    google.auth operations are synchronous — we run them in a thread executor.
    Raises if FIREBASE_SERVICE_ACCOUNT_PATH doesn't exist or credentials are invalid.
    """
    global _token_lock
    if _token_lock is None:
        _token_lock = asyncio.Lock()

    async with _token_lock:
        now = time.time()
        if _token_cache["token"] and now < _token_cache["expires_at"] - 300:
            return _token_cache["token"]

        from google.auth.transport.requests import Request
        from google.oauth2 import service_account

        creds = service_account.Credentials.from_service_account_file(
            settings.FIREBASE_SERVICE_ACCOUNT_PATH,
            scopes=FCM_SCOPES,
        )
        loop = asyncio.get_event_loop()
        await loop.run_in_executor(None, creds.refresh, Request())

        _token_cache["token"] = creds.token
        _token_cache["expires_at"] = creds.expiry.timestamp() if creds.expiry else (now + 3600)
        logger.debug("FCM access token refreshed, expires at %s", _token_cache["expires_at"])
        return _token_cache["token"]


# ── Result type ───────────────────────────────────────────────────────────────

@dataclass
class FcmResult:
    status: Literal["success", "token_invalid", "retryable", "failed"]
    error: str | None = None


# ── Sender ────────────────────────────────────────────────────────────────────

async def send_fcm(
    token: str,
    message_payload: dict,
    db: AsyncSession | None = None,
) -> FcmResult:
    """
    Deliver a single FCM message.

    On token_invalid (404 / UNREGISTERED): clears the token from users table
    if *db* is provided. Does not raise — returns an FcmResult.
    """
    if not settings.FIREBASE_PROJECT_ID:
        logger.warning("FIREBASE_PROJECT_ID not configured — skipping FCM send")
        return FcmResult(status="failed", error="firebase_not_configured")

    try:
        access_token = await _get_access_token()
    except Exception as exc:
        logger.error("FCM token refresh failed: %s", exc)
        return FcmResult(status="retryable", error=str(exc))

    url = FCM_SEND_URL.format(project_id=settings.FIREBASE_PROJECT_ID)
    body = {"message": {"token": token, **message_payload}}

    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.post(
                url,
                json=body,
                headers={"Authorization": f"Bearer {access_token}"},
            )
    except (httpx.TimeoutException, httpx.ConnectError) as exc:
        logger.warning("FCM network error: %s", exc)
        return FcmResult(status="retryable", error=str(exc))

    if resp.status_code == 200:
        return FcmResult(status="success")

    if resp.status_code == 404 or _is_unregistered(resp):
        logger.info("FCM token invalid (404/UNREGISTERED), clearing from DB")
        if db:
            await db.execute(
                update(_get_user_model()).where(
                    _get_user_model().fcm_token == token
                ).values(fcm_token=None)
            )
            await db.commit()
        return FcmResult(status="token_invalid", error="unregistered")

    if resp.status_code in (429,) or resp.status_code >= 500:
        logger.warning("FCM transient error %d", resp.status_code)
        return FcmResult(status="retryable", error=f"http_{resp.status_code}")

    # Other 4xx — permanent failure
    logger.error("FCM permanent error %d: %s", resp.status_code, resp.text[:200])
    return FcmResult(status="failed", error=f"http_{resp.status_code}")


def _is_unregistered(resp: httpx.Response) -> bool:
    """Check response body for UNREGISTERED error code."""
    try:
        body = resp.json()
        error_code = body.get("error", {}).get("details", [{}])[0].get("errorCode", "")
        return error_code == "UNREGISTERED"
    except Exception:
        return False


def _get_user_model():
    from app.models.user import User
    return User


# ── Notification payload builders ─────────────────────────────────────────────

def build_message_notification(
    sender_name: str,
    preview: str,
    conversation_id: str,
    message_id: str,
    sender_id: str,
) -> dict:
    """
    Standard chat message notification.
    android.priority=NORMAL, channel_id="messages".
    Body preview is generic for media types.
    """
    return {
        "notification": {
            "title": sender_name,
            "body": preview[:100],  # cap preview length
        },
        "android": {
            "priority": "NORMAL",
            "notification": {
                "channel_id": "messages",
                "default_sound": True,
            },
        },
        "data": {
            # IDs only — no message content, no secrets
            "type": "new_message",
            "conversation_id": conversation_id,
            "message_id": message_id,
            "sender_id": sender_id,
        },
        "apns": {
            "payload": {
                "aps": {
                    "alert": {"title": sender_name, "body": preview[:100]},
                    "sound": "default",
                }
            }
        },
    }


def build_call_notification(
    call_id: str,
    caller_id: str,
    caller_name: str,
    caller_avatar: str | None,
    call_type: str,
    sdp_offer: str,
    signal_token: str,
) -> dict:
    """
    Incoming call — data-only, HIGH priority, 30s TTL.
    Data-only so the OS delivers it even when the app is killed.
    signal_token (~60s JWT) lets the woken app join signaling without a login round-trip.
    """
    return {
        "android": {
            "priority": "HIGH",
            "ttl": "30s",
        },
        "data": {
            # IDs + SDP only — no persistent secrets
            "type": "incoming_call",
            "call_id": call_id,
            "caller_id": caller_id,
            "caller_name": caller_name,
            "caller_avatar": caller_avatar or "",
            "call_type": call_type,
            "sdp_offer": sdp_offer,
            "signal_token": signal_token,
        },
        "apns": {
            "headers": {
                "apns-push-type": "voip",
                "apns-priority": "10",
                "apns-expiration": "30",
            },
            "payload": {
                "aps": {"content-available": 1},
                "type": "incoming_call",
                "call_id": call_id,
                "signal_token": signal_token,
            },
        },
    }


def _media_preview(message_type: str) -> str:
    """Return a generic preview string for media messages."""
    return {
        "image": "📷 Photo",
        "video": "🎥 Video",
        "audio": "🎤 Voice message",
        "document": "📄 Document",
    }.get(message_type, "New message")

class AppError(Exception):
    """Base application error — carries HTTP status, machine code, and human detail."""

    def __init__(self, status_code: int, code: str, detail: str) -> None:
        self.status_code = status_code
        self.code = code
        self.detail = detail
        super().__init__(detail)


class NotFoundError(AppError):
    def __init__(self, detail: str = "Not found") -> None:
        super().__init__(404, "not_found", detail)


class UnauthorizedError(AppError):
    def __init__(self, detail: str = "Unauthorized") -> None:
        super().__init__(401, "unauthorized", detail)


class ForbiddenError(AppError):
    def __init__(self, detail: str = "Forbidden") -> None:
        super().__init__(403, "forbidden", detail)


class ConflictError(AppError):
    def __init__(self, detail: str = "Conflict") -> None:
        super().__init__(409, "conflict", detail)


class RateLimitError(AppError):
    def __init__(self, detail: str = "Rate limit exceeded") -> None:
        super().__init__(429, "rate_limit_exceeded", detail)


class ValidationFailedError(AppError):
    def __init__(self, detail: str = "Validation failed") -> None:
        super().__init__(422, "validation_failed", detail)


class UnsupportedMediaTypeError(AppError):
    def __init__(self, detail: str = "Unsupported media type") -> None:
        super().__init__(415, "unsupported_media_type", detail)


class FileTooLargeError(AppError):
